//! Jackson-compatible JSON helpers: the coercions the original's ObjectMapper
//! applies when binding request bodies, and the Java `toString` formats that
//! the original stores in text columns.

use chrono::NaiveDate;
use serde_json::{Map, Number, Value};

/// A JSON binding failure. The original's Jackson raises an exception here;
/// the controller turns it into a status code, so the detail is only logged.
#[derive(Debug)]
pub struct JErr(pub String);

pub type JResult<T> = Result<T, JErr>;

pub fn err<T>(msg: impl Into<String>) -> JResult<T> {
    Err(JErr(msg.into()))
}

/// Integer property (`Integer`, nullable): null stays null.
pub fn int_opt(v: &Value) -> JResult<Option<i32>> {
    match v {
        Value::Null => Ok(None),
        Value::Number(n) => {
            if let Some(i) = n.as_i64() {
                i32::try_from(i).map(Some).or_else(|_| err("int overflow"))
            } else if let Some(f) = n.as_f64() {
                // Jackson accepts floats for ints and truncates them.
                if f.is_finite() && f.abs() < i32::MAX as f64 {
                    Ok(Some(f.trunc() as i32))
                } else {
                    err("int overflow")
                }
            } else {
                err("int")
            }
        }
        Value::String(s) => {
            let t = s.trim();
            if t.is_empty() {
                return Ok(None);
            }
            t.parse::<i32>().map(Some).or_else(|_| err("not an int"))
        }
        _ => err("not an int"),
    }
}

/// Primitive `int`: null becomes 0.
pub fn int_prim(v: &Value) -> JResult<i32> {
    Ok(int_opt(v)?.unwrap_or(0))
}

/// Boolean wrapper: null stays null; numbers are non-zero, strings must be true/false.
pub fn bool_opt(v: &Value) -> JResult<Option<bool>> {
    match v {
        Value::Null => Ok(None),
        Value::Bool(b) => Ok(Some(*b)),
        Value::Number(n) => Ok(Some(n.as_f64().map(|f| f != 0.0).unwrap_or(false))),
        Value::String(s) => match s.as_str() {
            "true" | "True" | "TRUE" => Ok(Some(true)),
            "false" | "False" | "FALSE" | "" => Ok(Some(false)),
            _ => err("not a boolean"),
        },
        _ => err("not a boolean"),
    }
}

/// Primitive `boolean`: null becomes false.
pub fn bool_prim(v: &Value) -> JResult<bool> {
    Ok(bool_opt(v)?.unwrap_or(false))
}

/// String property: scalars are converted to their text form.
pub fn string_opt(v: &Value) -> JResult<Option<String>> {
    match v {
        Value::Null => Ok(None),
        Value::String(s) => Ok(Some(s.clone())),
        Value::Number(n) => Ok(Some(n.to_string())),
        Value::Bool(b) => Ok(Some(b.to_string())),
        _ => err("not a string"),
    }
}

/// Double wrapper.
pub fn f64_opt(v: &Value) -> JResult<Option<f64>> {
    match v {
        Value::Null => Ok(None),
        Value::Number(n) => Ok(n.as_f64()),
        Value::String(s) => {
            let t = s.trim();
            if t.is_empty() {
                return Ok(None);
            }
            t.parse::<f64>().map(Some).or_else(|_| err("not a double"))
        }
        _ => err("not a double"),
    }
}

pub fn date_opt(v: &Value) -> JResult<Option<NaiveDate>> {
    match v {
        Value::Null => Ok(None),
        Value::String(s) => NaiveDate::parse_from_str(s.trim(), "%Y-%m-%d")
            .map(Some)
            .or_else(|_| err("not a date")),
        _ => err("not a date"),
    }
}

/// `java.util.Locale` as Jackson reads it and Hibernate stores it (`Locale.toString()`).
pub fn locale_opt(v: &Value) -> JResult<Option<String>> {
    match v {
        Value::Null => Ok(None),
        Value::String(s) => {
            let parts: Vec<&str> = s.splitn(3, |c| c == '-' || c == '_').collect();
            let lang = parts[0].to_lowercase();
            if parts.len() == 1 {
                return Ok(Some(lang));
            }
            let country = parts[1].to_uppercase();
            if parts.len() == 2 {
                return Ok(Some(format!("{}_{}", lang, country)));
            }
            Ok(Some(format!("{}_{}_{}", lang, country, parts[2])))
        }
        _ => err("not a locale"),
    }
}

pub fn obj<'a>(v: &'a Value) -> JResult<&'a Map<String, Value>> {
    match v {
        Value::Object(m) => Ok(m),
        _ => err("expected an object"),
    }
}

pub fn array<'a>(v: &'a Value) -> JResult<&'a Vec<Value>> {
    match v {
        Value::Array(a) => Ok(a),
        _ => err("expected an array"),
    }
}

pub fn f64_val(x: f64) -> Value {
    Number::from_f64(x).map(Value::Number).unwrap_or(Value::Null)
}

/// Commons-Lang `NumberUtils.isParsable`, as used by the property converter.
fn is_parsable(s: &str) -> bool {
    if s.is_empty() || s.ends_with('.') {
        return false;
    }
    let body = if let Some(rest) = s.strip_prefix('-') {
        if rest.is_empty() {
            return false;
        }
        rest
    } else {
        s
    };
    let mut dots = 0;
    for ch in body.chars() {
        if ch == '.' {
            dots += 1;
            if dots > 1 {
                return false;
            }
        } else if !ch.is_ascii_digit() {
            return false;
        }
    }
    true
}

fn is_digits(s: &str) -> bool {
    !s.is_empty() && s.chars().all(|c| c.is_ascii_digit())
}

/// `AttributeConverter.convertToEntityAttribute` of the original's PropertyValueConverter.
pub fn property_from_db(s: &str) -> Value {
    if s.eq_ignore_ascii_case("true") {
        return Value::Bool(true);
    }
    if s.eq_ignore_ascii_case("false") {
        return Value::Bool(false);
    }
    if is_parsable(s) {
        if is_digits(s) || (s.starts_with('-') && is_digits(&s[1..])) {
            if let Ok(l) = s.parse::<i64>() {
                return Value::Number(Number::from(l));
            }
        } else if let Ok(d) = s.parse::<f64>() {
            return f64_val(d);
        }
    }
    Value::String(s.to_string())
}

/// `attribute.toString()` of the original's PropertyValueConverter.
pub fn property_to_db(v: &Value) -> JResult<String> {
    match v {
        Value::Null => err("null property value"),
        Value::Bool(b) => Ok(b.to_string()),
        Value::String(s) => Ok(s.clone()),
        Value::Number(n) => {
            if let Some(i) = n.as_i64() {
                Ok(i.to_string())
            } else {
                Ok(java_double(n.as_f64().unwrap_or(0.0)))
            }
        }
        other => Ok(java_tostring(other)),
    }
}

/// Java's `toString()` of the Map/List/scalar values Jackson builds.
pub fn java_tostring(v: &Value) -> String {
    match v {
        Value::Null => "null".to_string(),
        Value::Bool(b) => b.to_string(),
        Value::String(s) => s.clone(),
        Value::Number(n) => match n.as_i64() {
            Some(i) => i.to_string(),
            None => java_double(n.as_f64().unwrap_or(0.0)),
        },
        Value::Array(a) => {
            let parts: Vec<String> = a.iter().map(java_tostring).collect();
            format!("[{}]", parts.join(", "))
        }
        Value::Object(m) => {
            let parts: Vec<String> = m
                .iter()
                .map(|(k, v)| format!("{}={}", k, java_tostring(v)))
                .collect();
            format!("{{{}}}", parts.join(", "))
        }
    }
}

/// `Double.toString(d)`.
pub fn java_double(d: f64) -> String {
    if d.is_nan() {
        return "NaN".into();
    }
    if d.is_infinite() {
        return if d > 0.0 { "Infinity".into() } else { "-Infinity".into() };
    }
    if d == 0.0 {
        return if d.is_sign_negative() { "-0.0".into() } else { "0.0".into() };
    }
    // Shortest round-trip digits and exponent, from Rust's `{:e}`.
    let sci = format!("{:e}", d.abs());
    let (mant, exp) = sci.split_once('e').unwrap();
    let exp: i32 = exp.parse().unwrap();
    let digits: String = mant.chars().filter(|c| c.is_ascii_digit()).collect();
    let sign = if d < 0.0 { "-" } else { "" };
    let abs = d.abs();
    if (1e-3..1e7).contains(&abs) {
        // plain decimal notation
        let point = exp + 1; // digits before the decimal point
        let mut out = String::new();
        if point <= 0 {
            out.push_str("0.");
            for _ in 0..(-point) {
                out.push('0');
            }
            out.push_str(&digits);
        } else {
            let p = point as usize;
            if digits.len() <= p {
                out.push_str(&digits);
                for _ in 0..(p - digits.len()) {
                    out.push('0');
                }
                out.push_str(".0");
            } else {
                out.push_str(&digits[..p]);
                out.push('.');
                out.push_str(&digits[p..]);
            }
        }
        format!("{}{}", sign, out)
    } else {
        let first = &digits[..1];
        let rest = if digits.len() > 1 { &digits[1..] } else { "0" };
        format!("{}{}.{}E{}", sign, first, rest, exp)
    }
}

