}

impl Point {
    pub fn from_json(v: &Value) -> JResult<Option<Point>> {
        match v {
            Value::Null => Ok(None),
            Value::Object(m) => {
                let mut p = Point::default();
                for (k, val) in m {
                    match k.as_str() {
                        "x" => p.x = f64_opt(val)?.unwrap_or(0.0),
                        "y" => p.y = f64_opt(val)?.unwrap_or(0.0),
                        _ => return err("unknown point property"),
                    }
                }
                Ok(Some(p))
            }
            _ => err("expected a point"),
        }
    }

    pub fn to_json(&self) -> Value {
        json!({ "x": f64_val(self.x), "y": f64_val(self.y) })
    }
}

fn point_json(o: &Option<Point>) -> Value {
    null_or(o, |p| p.to_json())
}

