#[derive(Clone, Debug)]
pub struct TileGrid {
    pub id: Option<i32>,
    pub type_: Option<String>,
    pub origin: Option<Point>,
    pub extent: Option<Extent>,
    pub tile_size: Option<i32>,
    pub resolutions: Option<Vec<f64>>,
    /// Only for `WmtsTileGrid`.
    pub matrix_ids: Option<Vec<String>>,
    pub wmts: bool,
}

impl TileGrid {
    /// `new TileGrid()` (or `new WmtsTileGrid()` when `wmts`).
    pub fn detached(wmts: bool) -> TileGrid {
        TileGrid {
            id: None,
            type_: None,
            origin: None,
            extent: None,
            tile_size: Some(256),
            resolutions: None,
            matrix_ids: None,
            wmts,
        }
    }

    pub fn apply(&mut self, k: &str, v: &Value) -> JResult<()> {
        match k {
            "id" => self.id = int_opt(v)?,
            "type" => self.type_ = string_opt(v)?,
            "tileGridOrigin" => self.origin = Point::from_json(v)?,
            "tileGridExtent" => self.extent = Extent::from_json(v)?,
            "tileSize" => self.tile_size = int_opt(v)?,
            "tileGridResolutions" => self.resolutions = f64_list(v)?,
            "matrixIds" if self.wmts => self.matrix_ids = str_list(v)?,
            _ => return err(format!("unknown property {k} on TileGrid")),
        }
        Ok(())
    }

    /// Binds a nested tile grid object (or null).
    pub fn from_json(v: &Value, wmts: bool) -> JResult<Option<TileGrid>> {
        match v {
            Value::Null => Ok(None),
            _ => {
                let mut t = TileGrid::detached(wmts);
                for (k, val) in obj(v)? {
                    if is_ignored_prop(k) {
                        continue;
                    }
                    t.apply(k, val)?;
                }
                Ok(Some(t))
            }
        }
    }

    pub fn to_json(&self) -> Value {
        let mut m = Map::new();
        m.insert("id".into(), opt_i32(&self.id));
        m.insert("type".into(), opt_str(&self.type_));
        m.insert("tileGridOrigin".into(), point_json(&self.origin));
        m.insert("tileGridExtent".into(), extent_json(&self.extent));
        m.insert("tileSize".into(), opt_i32(&self.tile_size));
        m.insert(
            "tileGridResolutions".into(),
            vec_json(&self.resolutions, |d| f64_val(*d)),
        );
        if self.wmts {
            m.insert("matrixIds".into(), vec_json(&self.matrix_ids, |s| Value::String(s.clone())));
        }
        Value::Object(m)
    }
}

fn tile_grid_json(o: &Option<TileGrid>) -> Value {
    null_or(o, |t| t.to_json())
}

fn f64_list(v: &Value) -> JResult<Option<Vec<f64>>> {
    match v {
        Value::Null => Ok(None),
        _ => array(v)?
            .iter()
            .map(|x| f64_opt(x)?.ok_or_else(|| JErr("null element".into())))
            .collect::<JResult<Vec<_>>>()
            .map(Some),
    }
}

fn str_list(v: &Value) -> JResult<Option<Vec<String>>> {
    match v {
        Value::Null => Ok(None),
        _ => array(v)?
            .iter()
            .map(|x| string_opt(x)?.ok_or_else(|| JErr("null element".into())))
            .collect::<JResult<Vec<_>>>()
            .map(Some),
    }
}

