// ---------------------------------------------------------------- User

#[derive(Clone, Debug)]
pub struct User {
    pub id: Option<i32>,
    pub first_name: Option<String>,
    pub last_name: Option<String>,
    pub email: Option<String>,
    pub birthday: Option<NaiveDate>,
    pub language: Option<String>,
    pub account_name: Option<String>,
    pub password: Option<String>,
    pub active: bool,
    pub roles: Option<Vec<Role>>,
    /// Ids of the user's groups (the original serializes them as ids only).
    pub user_groups: Option<Vec<Option<i32>>>,
}

impl Default for User {
    fn default() -> Self {
        // `new User()`: the collections are initialised to empty sets.
        User {
            id: None,
            first_name: None,
            last_name: None,
            email: None,
            birthday: None,
            language: None,
            account_name: None,
            password: None,
            active: false,
            roles: Some(vec![]),
            user_groups: Some(vec![]),
        }
    }
}

impl User {
    pub fn apply(&mut self, k: &str, v: &Value) -> JResult<()> {
        match k {
            "id" => self.id = int_opt(v)?,
            "firstName" => self.first_name = string_opt(v)?,
            "lastName" => self.last_name = string_opt(v)?,
            "email" => self.email = string_opt(v)?,
            "birthday" => self.birthday = date_opt(v)?,
            "language" => self.language = locale_opt(v)?,
            "accountName" => self.account_name = string_opt(v)?,
            "password" => self.password = string_opt(v)?,
            "active" => self.active = bool_prim(v)?,
            "roles" => {
                self.roles = match v {
                    Value::Null => None,
                    _ => Some(
                        array(v)?
                            .iter()
                            .map(Role::from_json)
                            .collect::<JResult<Vec<_>>>()?,
                    ),
                }
            }
            "userGroups" => {
                self.user_groups = match v {
                    Value::Null => None,
                    _ => Some(
                        array(v)?
                            .iter()
                            .map(group_ref)
                            .collect::<JResult<Vec<_>>>()?,
                    ),
                }
            }
            _ => return err(format!("unknown property {k} on User")),
        }
        Ok(())
    }

    pub fn from_json(v: &Value) -> JResult<User> {
        let mut u = User::default();
        for (k, val) in obj(v)? {
            if is_ignored_prop(k) {
                continue;
            }
            u.apply(k, val)?;
        }
        Ok(u)
    }

    /// The bean the original builds for a restricted (projection) query.
    pub fn bean() -> User {
        User::default()
    }

    pub fn to_json(&self) -> Value {
        // `password` is write-only.
        json!({
            "id": opt_i32(&self.id),
            "firstName": opt_str(&self.first_name),
            "lastName": opt_str(&self.last_name),
            "email": opt_str(&self.email),
            "birthday": null_or(&self.birthday, |d| Value::String(d.format("%Y-%m-%d").to_string())),
            "language": opt_str(&self.language),
            "accountName": opt_str(&self.account_name),
            "active": self.active,
            "roles": vec_json(&self.roles, |r| r.to_json()),
            "userGroups": vec_json(&self.user_groups, |g| opt_i32(g)),
        })
    }
}

/// A group referenced from a user's `userGroups` (an id, or an object with an id).
fn group_ref(v: &Value) -> JResult<Option<i32>> {
    match v {
        Value::Object(_) => Ok(UserGroup::from_json(v)?.id),
        Value::Null => err("null group reference"),
        _ => int_opt(v),
    }
}

