}

pub async fn update_user(c: &mut Conn, u: &User, touched: &Touched) -> R<()> {
    let id = check_id(u.id)?;
    let res = sqlx::query(
        "UPDATE persons SET modified = localtimestamp, birthday = $2, email = $3, \
         firstname = $4, language = $5, lastname = $6 WHERE id = $1",
    )
    .bind(id)
    .bind(u.birthday)
    .bind(&u.email)
    .bind(&u.first_name)
    .bind(&u.language)
    .bind(&u.last_name)
    .execute(&mut *c)
    .await?;
    expect_one(res).await?;
    let res = sqlx::query("UPDATE users SET accountname = $2, active = $3, password = $4 WHERE id = $1")
        .bind(id)
        .bind(&u.account_name)
        .bind(u.active)
        .bind(&u.password)
        .execute(&mut *c)
        .await?;
    expect_one(res).await?;
    if touched.has("roles") {
        sqlx::query("DELETE FROM users_roles WHERE user_id = $1")
            .bind(id)
            .execute(&mut *c)
            .await?;
    }
    if touched.has("userGroups") {
        sqlx::query("DELETE FROM user_usergroup WHERE user_id = $1")
            .bind(id)
            .execute(&mut *c)
            .await?;
    }
    let only_roles = Some(u.roles.clone()).filter(|_| touched.has("roles"));
    let only_groups = Some(u.user_groups.clone()).filter(|_| touched.has("userGroups"));
    let tmp = User {
        roles: only_roles.flatten(),
        user_groups: only_groups.flatten(),
        id: Some(id),
        ..User::default()
    };
    insert_user_rows(c, &tmp).await
}

pub async fn delete_user(c: &mut Conn, id: i32) -> R<()> {
    sqlx::query("DELETE FROM users_roles WHERE user_id = $1")
        .bind(id)
        .execute(&mut *c)
        .await?;
    sqlx::query("DELETE FROM user_usergroup WHERE user_id = $1")
        .bind(id)
        .execute(&mut *c)
        .await?;
    delete_perm_rows(c, id).await?;
    let res = sqlx::query("DELETE FROM users WHERE id = $1")
        .bind(id)
        .execute(&mut *c)
        .await?;
    expect_one(res).await?;
    let res = sqlx::query("DELETE FROM persons WHERE id = $1")
        .bind(id)
        .execute(&mut *c)
        .await?;
    expect_one(res).await
}

async fn insert_group_rows(c: &mut Conn, g: &UserGroup) -> R<()> {
    if let Some(members) = &g.members {
        let mut ids = Vec::new();
        for m in members {
            ids.push(check_id(m.id)?);
        }
        let ids = dedupe_by_id(ids.into_iter().map(|i| (Some(i), i)).collect())?;
        for uid in ids {
            sqlx::query("INSERT INTO user_usergroup (usergroup_id, user_id) VALUES ($1, $2)")
                .bind(g.id)
                .bind(uid)
                .execute(&mut *c)
                .await?;
        }
    }
    if let Some(roles) = &g.roles {
        let mut ids = Vec::new();
        for r in roles {
            ids.push(check_id(r.id)?);
        }
        let ids = dedupe_by_id(ids.into_iter().map(|i| (Some(i), i)).collect())?;
        for rid in ids {
            sqlx::query("INSERT INTO usergroups_roles (usergroup_id, role_id) VALUES ($1, $2)")
                .bind(g.id)
                .bind(rid)
                .execute(&mut *c)
                .await?;
        }
    }
    Ok(())
}

