    if let Some(roles) = &u.roles {
        let ids = dedupe_by_id(roles.iter().map(|r| (r.id, r.id)).collect())?;
        for rid in ids {
            sqlx::query("INSERT INTO users_roles (user_id, role_id) VALUES ($1, $2)")
                .bind(u.id)
                .bind(rid)
                .execute(&mut *c)
                .await?;
        }
    }
    if let Some(groups) = &u.user_groups {
        let mut ids = Vec::new();
        for g in groups {
            ids.push(check_id(*g)?);
        }
        let ids = dedupe_by_id(ids.into_iter().map(|i| (Some(i), i)).collect())?;
        for gid in ids {
            sqlx::query("INSERT INTO user_usergroup (usergroup_id, user_id) VALUES ($1, $2)")
                .bind(gid)
                .bind(u.id)
                .execute(&mut *c)
                .await?;
        }
    }
    Ok(())
}

