pub async fn save_extent(c: &mut Conn, pool: &PgPool, e: &mut Extent, original_id: Option<i32>, nested: bool) -> R<()> {
    let (ll, ur) = (e.lower_left.clone(), e.upper_right.clone());
    match e.id {
        None => {
            let id = next_id(pool).await?;
            e.id = Some(id);
            sqlx::query(
                "INSERT INTO extents (id, created, modified, lowerleft_x, lowerleft_y, \
                 upperright_x, upperright_y) VALUES ($1, localtimestamp, localtimestamp, $2, $3, $4, $5)",
            )
            .bind(id)
            .bind(ll.as_ref().map(|p| p.x))
            .bind(ll.as_ref().map(|p| p.y))
            .bind(ur.as_ref().map(|p| p.x))
            .bind(ur.as_ref().map(|p| p.y))
            .execute(&mut *c)
            .await?;
        }
        Some(id) => {
            if nested && original_id == Some(id) {
                return bad("NonUniqueObjectException");
            }
            let res = sqlx::query(
                "UPDATE extents SET modified = localtimestamp, lowerleft_x = $2, lowerleft_y = $3, \
                 upperright_x = $4, upperright_y = $5 WHERE id = $1",
            )
            .bind(id)
            .bind(ll.as_ref().map(|p| p.x))
            .bind(ll.as_ref().map(|p| p.y))
            .bind(ur.as_ref().map(|p| p.x))
            .bind(ur.as_ref().map(|p| p.y))
            .execute(&mut *c)
            .await?;
            expect_one(res).await?;
        }
    }
    Ok(())
}

/// Saves a tile grid as a cascaded (nested) object: always written in full.
/// `orig_tg` / `orig_ext` are the ids the original session already holds.
pub async fn save_tile_grid(
    c: &mut Conn,
    pool: &PgPool,
    t: &mut TileGrid,
    orig_tg: Option<i32>,
    orig_ext: Option<i32>,
) -> R<()> {
    let is_new = t.id.is_none();
    if is_new {
        // parent first: the id is allocated before the extent cascade
        let id = next_id(pool).await?;
        t.id = Some(id);
    } else if orig_tg == t.id {
        return bad("NonUniqueObjectException");
    }
    if let Some(e) = t.extent.as_mut() {
        save_extent(c, pool, e, orig_ext, true).await?;
    }
    let id = check_id(t.id)?;
    let ext_id = t.extent.as_ref().and_then(|e| e.id);
    let origin = t.origin.clone();
    if is_new {
        sqlx::query(
            "INSERT INTO tilegrids (id, created, modified, tilegridorigin_x, tilegridorigin_y, \
             tilesize, type, tilegridextent_id) \
             VALUES ($1, localtimestamp, localtimestamp, $2, $3, $4, $5, $6)",
        )
        .bind(id)
        .bind(origin.as_ref().map(|p| p.x))
        .bind(origin.as_ref().map(|p| p.y))
        .bind(t.tile_size)
        .bind(&t.type_)
        .bind(ext_id)
        .execute(&mut *c)
        .await?;
        if t.wmts {
            sqlx::query("INSERT INTO wmtstilegrids (id) VALUES ($1)")
                .bind(id)
                .execute(&mut *c)
                .await?;
        }
    } else {
        let res = sqlx::query(
            "UPDATE tilegrids SET modified = localtimestamp, tilegridorigin_x = $2, \
             tilegridorigin_y = $3, tilesize = $4, type = $5, tilegridextent_id = $6 WHERE id = $1",
        )
        .bind(id)
        .bind(origin.as_ref().map(|p| p.x))
        .bind(origin.as_ref().map(|p| p.y))
        .bind(t.tile_size)
        .bind(&t.type_)
        .bind(ext_id)
        .execute(&mut *c)
        .await?;
        expect_one(res).await?;
    }
    // element collections of a detached object are always recreated
    sqlx::query("DELETE FROM tilegrid_resolution WHERE tilegrid_id = $1")
        .bind(id)
        .execute(&mut *c)
        .await?;
    if let Some(res) = &t.resolutions {
        for (idx, r) in res.iter().enumerate() {
            sqlx::query(
                "INSERT INTO tilegrid_resolution (tilegrid_id, resolution, idx) VALUES ($1, $2, $3)",
            )
            .bind(id)
            .bind(*r)
            .bind(idx as i32)
            .execute(&mut *c)
            .await?;
        }
    }
    if t.wmts {
        sqlx::query("DELETE FROM wmtstilegrids_matrixids WHERE wmtstilegrids_id = $1")
            .bind(id)
            .execute(&mut *c)
            .await?;
        if let Some(ids) = &t.matrix_ids {
            for m in ids {
                sqlx::query(
                    "INSERT INTO wmtstilegrids_matrixids (wmtstilegrids_id, matrixids) VALUES ($1, $2)",
                )
                .bind(id)
                .bind(m)
                .execute(&mut *c)
                .await?;
            }
        }
    }
    Ok(())
}

/// Deletes a WmtsTileGrid (cascade REMOVE of the Wmts data source).
async fn delete_wmts_tile_grid(c: &mut Conn, id: i32) -> R<()> {
    sqlx::query("DELETE FROM wmtstilegrids_matrixids WHERE wmtstilegrids_id = $1")
        .bind(id)
        .execute(&mut *c)
        .await?;
    sqlx::query("DELETE FROM tilegrid_resolution WHERE tilegrid_id = $1")
        .bind(id)
        .execute(&mut *c)
        .await?;
    sqlx::query("DELETE FROM wmtstilegrids WHERE id = $1")
        .bind(id)
        .execute(&mut *c)
        .await?;
    let res = sqlx::query("DELETE FROM tilegrids WHERE id = $1")
        .bind(id)
        .execute(&mut *c)
        .await?;
    expect_one(res).await
}

/// Writes the entity behind an update of a managed data source.
pub async fn update_ds(
    c: &mut Conn,
    pool: &PgPool,
    d: &mut DataSource,
    orig: &DataSource,
    touched: &Touched,
) -> R<()> {
    let id = check_id(d.id)?;
    let res = sqlx::query(
        "UPDATE layerdatasources SET modified = localtimestamp, format = $2, name = $3, \
         type = $4, url = $5 WHERE id = $1",
    )
    .bind(id)
    .bind(&d.format)
    .bind(&d.name)
    .bind(&d.type_)
    .bind(&d.url)
    .execute(&mut *c)
    .await?;
    expect_one(res).await?;
    let orig_tg = match &orig.kind {
        DsKind::TileWms(t) => t.tile_grid.as_ref().and_then(|g| g.id),
        DsKind::Wmts(w) => w.tile_grid.as_ref().and_then(|g| g.id),
        _ => None,
    };
    let orig_ext = match &orig.kind {
        DsKind::TileWms(t) => t.tile_grid.as_ref().and_then(|g| g.extent.as_ref()).and_then(|e| e.id),
        DsKind::Wmts(w) => w.tile_grid.as_ref().and_then(|g| g.extent.as_ref()).and_then(|e| e.id),
        _ => None,
    };
    match &mut d.kind {
        DsKind::ImageWms(i) => update_image(c, id, i).await?,
        DsKind::TileWms(t) => {
            if let Some(tg) = t.tile_grid.as_mut() {
                save_tile_grid(c, pool, tg, orig_tg, orig_ext).await?;
            }
            update_image(c, id, &t.image).await?;
            let tg_id = t.tile_grid.as_ref().and_then(|g| g.id);
            let res = sqlx::query(
                "UPDATE tilewmslayerdatasources SET request_with_tiled = $2, tilegrid_id = $3 WHERE id = $1",
            )
            .bind(id)
            .bind(t.request_with_tiled)
            .bind(tg_id)
            .execute(&mut *c)
            .await?;
            expect_one(res).await?;
        }
        DsKind::Wfs(w) => {
            let res = sqlx::query(
                "UPDATE wfslayerdatasources SET typename = $2, typenames = $3, version = $4 WHERE id = $1",
            )
            .bind(id)
            .bind(&w.type_name)
            .bind(&w.type_names)
            .bind(&w.version)
            .execute(&mut *c)
            .await?;
            expect_one(res).await?;
        }
        DsKind::Wmts(w) => {
            if let Some(tg) = w.tile_grid.as_mut() {
                save_tile_grid(c, pool, tg, orig_tg, orig_ext).await?;
            }
            let tg_id = w.tile_grid.as_ref().and_then(|g| g.id);
            let res = sqlx::query(
                "UPDATE wmtslayerdatasources SET capabilitiesurl = $2, matrixset = $3, projection = $4, \
                 requestencoding = $5, wmtslayer = $6, wmtsstyle = $7, tilegrid_id = $8 WHERE id = $1",
            )
            .bind(id)
            .bind(&w.capabilities_url)
            .bind(&w.matrix_set)
            .bind(&w.projection)
            .bind(&w.request_encoding)
            .bind(&w.wmts_layer)
            .bind(&w.wmts_style)
            .bind(tg_id)
            .execute(&mut *c)
            .await?;
            expect_one(res).await?;
            if touched.has("urls") {
                sqlx::query("DELETE FROM wmtslayerdatasources_urls WHERE wmtslayerdatasources_id = $1")
                    .bind(id)
                    .execute(&mut *c)
                    .await?;
                if let Some(urls) = &w.urls {
                    for u in urls {
                        sqlx::query(
                            "INSERT INTO wmtslayerdatasources_urls (wmtslayerdatasources_id, urls) VALUES ($1, $2)",
                        )
                        .bind(id)
                        .bind(u)
                        .execute(&mut *c)
                        .await?;
                    }
                }
            }
        }
        DsKind::Xyz(x) => {
            let ext_id = match x.extent.as_mut() {
                // no cascade: the extent must exist already
                Some(e) => Some(check_id(e.id)?),
                None => None,
            };
            let res = sqlx::query(
                "UPDATE xyzlayerdatasources SET center_x = $2, center_y = $3, tilesize = $4, \
                 extent_id = $5 WHERE id = $1",
            )
            .bind(id)
            .bind(x.center.as_ref().map(|p| p.x))
            .bind(x.center.as_ref().map(|p| p.y))
            .bind(x.tile_size)
            .bind(ext_id)
            .execute(&mut *c)
            .await?;
            expect_one(res).await?;
            if touched.has("resolutions") {
                sqlx::query("DELETE FROM xyzlayerdatasrc_resolution WHERE xyzlayerdatasrc_id = $1")
                    .bind(id)
                    .execute(&mut *c)
                    .await?;
                if let Some(res) = &x.resolutions {
                    for (idx, r) in res.iter().enumerate() {
                        sqlx::query(
                            "INSERT INTO xyzlayerdatasrc_resolution (xyzlayerdatasrc_id, resolution, idx) \
                             VALUES ($1, $2, $3)",
                        )
                        .bind(id)
                        .bind(encode_java_double(*r))
                        .bind(idx as i32)
                        .execute(&mut *c)
                        .await?;
                    }
                }
            }
        }
    }
    Ok(())
}

async fn update_image(c: &mut Conn, id: i32, i: &ImageWms) -> R<()> {
    let res = sqlx::query(
        "UPDATE imagewmslayerdatasources SET customrequestpath = $2, height = $3, layernames = $4, \
         layerstyles = $5, requestablebypath = $6, version = $7, width = $8 WHERE id = $1",
    )
    .bind(id)
    .bind(&i.custom_request_path)
    .bind(i.height)
    .bind(&i.layer_names)
    .bind(&i.layer_styles)
    .bind(i.requestable_by_path)
    .bind(&i.version)
    .bind(i.width)
    .execute(&mut *c)
    .await?;
    expect_one(res).await
}

pub async fn delete_ds(c: &mut Conn, id: i32, kind_tile_grid_wmts: Option<i32>, kind: &DsKind) -> R<()> {
    match kind {
        DsKind::TileWms(_) => {
            sqlx::query("DELETE FROM tilewmslayerdatasources WHERE id = $1")
                .bind(id)
                .execute(&mut *c)
                .await?;
            sqlx::query("DELETE FROM imagewmslayerdatasources WHERE id = $1")
                .bind(id)
                .execute(&mut *c)
                .await?;
        }
        DsKind::ImageWms(_) => {
            sqlx::query("DELETE FROM imagewmslayerdatasources WHERE id = $1")
                .bind(id)
                .execute(&mut *c)
                .await?;
        }
        DsKind::Wfs(_) => {
            sqlx::query("DELETE FROM wfslayerdatasources WHERE id = $1")
                .bind(id)
                .execute(&mut *c)
                .await?;
        }
        DsKind::Wmts(_) => {
            sqlx::query("DELETE FROM wmtslayerdatasources_urls WHERE wmtslayerdatasources_id = $1")
                .bind(id)
                .execute(&mut *c)
                .await?;
            sqlx::query("DELETE FROM wmtslayerdatasources WHERE id = $1")
                .bind(id)
                .execute(&mut *c)
                .await?;
            // cascade = ALL on the tile grid
            if let Some(tg) = kind_tile_grid_wmts {
                delete_wmts_tile_grid(c, tg).await?;
            }
        }
        DsKind::Xyz(_) => {
            sqlx::query("DELETE FROM xyzlayerdatasrc_resolution WHERE xyzlayerdatasrc_id = $1")
                .bind(id)
                .execute(&mut *c)
                .await?;
            sqlx::query("DELETE FROM xyzlayerdatasources WHERE id = $1")
                .bind(id)
                .execute(&mut *c)
                .await?;
        }
    }
    delete_perm_rows(c, id).await?;
    let res = sqlx::query("DELETE FROM layerdatasources WHERE id = $1")
        .bind(id)
        .execute(&mut *c)
        .await?;
    expect_one(res).await
}

pub async fn save_layer_insert(c: &mut Conn, pool: &PgPool, l: &mut Layer) -> R<()> {
    // The layer's id comes first, then the cascaded appearance.
    let id = next_id(pool).await?;
    l.id = Some(id);
    if let Some(a) = l.appearance.as_mut() {
        save_appearance(c, pool, a, None, false, &Touched::default()).await?;
    }
    sqlx::query(
        "INSERT INTO layers (id, created, modified, description, name, appearance_id, source_id) \
         VALUES ($1, localtimestamp, localtimestamp, $2, $3, $4, $5)",
    )
    .bind(id)
    .bind(&l.description)
    .bind(&l.name)
    .bind(l.appearance.as_ref().and_then(|a| a.id))
    .bind(l.source.as_ref().and_then(|s| s.id))
    .execute(&mut *c)
    .await?;
    Ok(())
}

pub async fn save_layer_update(
    c: &mut Conn,
    pool: &PgPool,
    l: &mut Layer,
    orig_appearance: Option<i32>,
) -> R<()> {
    let id = check_id(l.id)?;
    if let Some(a) = l.appearance.as_mut() {
        save_appearance(c, pool, a, orig_appearance, true, &Touched::default()).await?;
    }
    let res = sqlx::query(
        "UPDATE layers SET modified = localtimestamp, description = $2, name = $3, \
         appearance_id = $4, source_id = $5 WHERE id = $1",
    )
    .bind(id)
    .bind(&l.description)
    .bind(&l.name)
    .bind(l.appearance.as_ref().and_then(|a| a.id))
    .bind(l.source.as_ref().and_then(|s| s.id))
    .execute(&mut *c)
    .await?;
    expect_one(res).await
}

pub async fn delete_layer(c: &mut Conn, id: i32) -> R<()> {
    delete_perm_rows(c, id).await?;
    let res = sqlx::query("DELETE FROM layers WHERE id = $1")
        .bind(id)
        .execute(&mut *c)
        .await?;
    expect_one(res).await
}

/// Ids of the maps (and their list index) that contain the layer.
pub async fn maps_with_layer(c: &mut Conn, layer_id: i32) -> R<Vec<i32>> {
    let rows = sqlx::query_scalar::<_, i32>(
        "SELECT DISTINCT map_id FROM maps_layers WHERE layer_id = $1 ORDER BY map_id",
    )
    .bind(layer_id)
    .fetch_all(&mut *c)
    .await?;
    Ok(rows)
}

/// Removes the first occurrence of the layer from a map's ordered layer list
/// and renumbers the list, as Hibernate does for an indexed collection.
pub async fn remove_layer_from_map(c: &mut Conn, map_id: i32, layer_id: i32) -> R<()> {
    let mut layers: Vec<i32> = sqlx::query_scalar(
        "SELECT layer_id FROM maps_layers WHERE map_id = $1 ORDER BY idx",
    )
    .bind(map_id)
    .fetch_all(&mut *c)
    .await?;
    if let Some(pos) = layers.iter().position(|l| *l == layer_id) {
        layers.remove(pos);
    }
    sqlx::query("DELETE FROM maps_layers WHERE map_id = $1")
        .bind(map_id)
        .execute(&mut *c)
        .await?;
    for (idx, l) in layers.iter().enumerate() {
        sqlx::query("INSERT INTO maps_layers (map_id, layer_id, idx) VALUES ($1, $2, $3)")
            .bind(map_id)
            .bind(l)
            .bind(idx as i32)
            .execute(&mut *c)
            .await?;
    }
    Ok(())
}

