//! The REST controllers: routing, the generic endpoints of AbstractRestController,
//! and the two sub-resources. Status codes follow the original's catch blocks.

use std::sync::Arc;

use axum::body::Body;
use axum::extract::{Request, State};
use axum::http::{HeaderMap, HeaderValue, Method, StatusCode, header};
use axum::response::Response;
use serde_json::{Map, Value, json};
use sqlx::PgPool;

use crate::auth::{self, Kind, Perm, Principal, ROLE_ADMIN, bean_has_perm, has_perm, kind_of};
use crate::json::{JErr, JResult, int_opt, obj};
use crate::model::*;
use crate::store::{self, Conn, DbFail, R, Touched};

pub struct AppState {
    pub pool: PgPool,
}

// ================================================================ entity wrapper

#[derive(Clone)]
pub enum Ent {
    User(User),
    Group(UserGroup),
    Role(Role),
    Layer(Layer),
    Ds(DataSource),
    App(Appearance),
}

impl Ent {
    fn id(&self) -> Option<i32> {
        match self {
            Ent::User(e) => e.id,
            Ent::Group(e) => e.id,
            Ent::Role(e) => e.id,
            Ent::Layer(e) => e.id,
            Ent::Ds(e) => e.id,
            Ent::App(e) => e.id,
        }
    }

    fn to_json(&self) -> Value {
        match self {
            Ent::User(e) => e.to_json(),
            Ent::Group(e) => e.to_json(),
            Ent::Role(e) => e.to_json(),
            Ent::Layer(e) => e.to_json(),
            Ent::Ds(e) => e.to_json(),
            Ent::App(e) => e.to_json(),
        }
    }

    fn cell(&self, f: &str) -> Cell {
        match self {
            Ent::User(e) => e.cell(f),
            Ent::Group(e) => e.cell(f),
            Ent::Role(e) => e.cell(f),
            Ent::Layer(e) => e.cell(f),
            Ent::Ds(e) => e.cell(f),
            Ent::App(e) => e.cell(f),
        }
    }

    /// Binds a JSON property onto the entity (Jackson's readerForUpdating).
    fn apply(&mut self, k: &str, v: &Value) -> JResult<()> {
        match self {
            Ent::User(e) => e.apply(k, v),
            Ent::Group(e) => e.apply(k, v),
            Ent::Role(e) => e.apply(k, v),
            Ent::Layer(e) => e.apply(k, v),
            Ent::Ds(e) => e.apply(k, v),
            Ent::App(e) => e.apply(k, v),
        }
    }
}

fn new_ent(res: Res) -> Ent {
    match res {
        Res::Users => Ent::User(User::default()),
        Res::Groups => Ent::Group(UserGroup::default()),
        Res::Roles => Ent::Role(Role::default()),
        Res::Layers => Ent::Layer(Layer::default()),
        Res::Appearances => Ent::App(Appearance::default()),
        // LayerDataSource is abstract: Jackson cannot construct it
        Res::DataSources => unreachable!("data sources are never created from JSON"),
    }
}

/// Keys whose value is a collection that a top-level update replaces.
fn collection_key(k: &str) -> Option<&'static str> {
    match k {
        "roles" => Some("roles"),
        "userGroups" => Some("userGroups"),
        "members" => Some("members"),
        "urls" => Some("urls"),
        "resolutions" => Some("resolutions"),
        "properties" => Some("properties"),
        _ => None,
    }
}

async fn load_ent(c: &mut Conn, res: Res, id: i32) -> R<Option<Ent>> {
    Ok(match res {
        Res::Users => store::load_user(c, id).await?.map(Ent::User),
        Res::Groups => store::load_group(c, id).await?.map(Ent::Group),
        Res::Roles => store::load_role(c, id).await?.map(Ent::Role),
        Res::Layers => store::load_layer(c, id).await?.map(Ent::Layer),
        Res::DataSources => store::load_ds(c, id).await?.map(Ent::Ds),
        Res::Appearances => store::load_appearance(c, id).await?.map(Ent::App),
    })
}

fn table_of(res: Res) -> &'static str {
    match res {
        Res::Users => "users",
        Res::Groups => "usergroups",
        Res::Roles => "roles",
        Res::Layers => "layers",
        Res::DataSources => "layerdatasources",
        Res::Appearances => "layerappearances",
    }
}

async fn load_all(c: &mut Conn, res: Res) -> R<Vec<Ent>> {
    let ids = store::all_ids(c, table_of(res)).await?;
    let mut out = Vec::with_capacity(ids.len());
    for id in ids {
        if let Some(e) = load_ent(c, res, id).await? {
            out.push(e);
        }
    }
    Ok(out)
}

fn kind_entity_kind(res: Res) -> Kind {
    kind_of(res)
}

// ================================================================ query parameters

/// `output:only` values, split the way the original's
/// `listFromCommaSeparatedStringList` does.
fn split_list(s: &str) -> Vec<String> {
    let pieces: Vec<&str> = s.split(',').collect();
    let n = pieces.len();
    let mut out: Vec<String> = pieces
        .iter()
        .enumerate()
        .map(|(i, p)| {
            let mut t: &str = p;
            if i > 0 {
                t = t.trim_start();
            }
            if i + 1 < n {
                t = t.trim_end();
            }
            t.to_string()
        })
        .collect();
    while out.len() > 1 && out.last().is_some_and(|s| s.is_empty()) {
        out.pop();
    }
    out
}

fn is_output_only(k: &str) -> bool {
    k.eq_ignore_ascii_case("output:only")
}

/// The restricted fields for `output:only`, in the entity's field order, or
/// `None` when no valid field was requested (a normal query then).
fn restrict_fields(query: &[(String, String)], res: Res) -> Option<Vec<&'static str>> {
    let mut requested: Option<Vec<String>> = None;
    let mut matched_key: Option<&str> = None;
    for (k, _) in query {
        if is_output_only(k) {
            matched_key = Some(k.as_str());
        }
    }
    if let Some(key) = matched_key {
        let mut vals = Vec::new();
        for (k, v) in query {
            if k == key {
                vals.extend(split_list(v));
            }
        }
        requested = Some(vals);
    }
    let requested = requested?;
    let fields: Vec<&'static str> = res
        .fields()
        .iter()
        .map(|(f, _)| *f)
        .filter(|f| requested.iter().any(|r| r.eq_ignore_ascii_case(f)))
        .collect();
    if fields.is_empty() { None } else { Some(fields) }
}

/// The equality conditions of a simple filter: field → converted values.
/// Fields not known to the entity class are ignored.
fn filter_conditions(query: &[(String, String)], res: Res) -> Vec<(&'static str, Vec<Cell>)> {
    let mut conds = Vec::new();
    let non_restrict: Vec<&(String, String)> = query
        .iter()
        .filter(|(k, _)| k != "output:only")
        .collect();
    for (f, ft) in res.fields() {
        let first_key = non_restrict
            .iter()
            .find(|(k, _)| k.eq_ignore_ascii_case(f))
            .map(|(k, _)| k.clone());
        if let Some(key) = first_key {
            let vals: Vec<Cell> = non_restrict
                .iter()
                .filter(|(k, _)| *k == key)
                .map(|(_, v)| convert_query_value(*ft, v))
                .collect();
            conds.push((*f, vals));
        }
    }
    conds
}

fn matches_conditions(e: &Ent, conds: &[(&'static str, Vec<Cell>)]) -> bool {
    conds
        .iter()
        .all(|(f, vals)| vals.iter().any(|v| e.cell(f) == *v))
}

fn restricted_json(res: Res, e: &Ent, fields: &[&'static str]) -> Value {
    let mut base = res_json_bean(res);
    if let Value::Object(m) = &mut base {
        for f in fields {
            if *f == "password" {
                continue; // write-only
            }
            m.insert((*f).to_string(), e.cell(f).to_json());
        }
    }
    base
}

// ================================================================ responses

fn json_response(status: StatusCode, body: &Value) -> Response {
    let bytes = serde_json::to_vec(body).unwrap_or_default();
    let mut resp = Response::new(Body::from(bytes));
    *resp.status_mut() = status;
    resp.headers_mut().insert(
        header::CONTENT_TYPE,
        HeaderValue::from_static("application/json;charset=UTF-8"),
    );
    resp
}

fn status_only(status: StatusCode) -> Response {
    let mut resp = Response::new(Body::empty());
    *resp.status_mut() = status;
    resp
}

fn unauthorized() -> Response {
    let mut resp = status_only(StatusCode::UNAUTHORIZED);
    resp.headers_mut().insert(
        header::WWW_AUTHENTICATE,
        HeaderValue::from_static("Basic realm=\"SHOGun Realm\""),
    );
    resp
}

fn bad_request() -> Response {
    status_only(StatusCode::BAD_REQUEST)
}

fn not_found() -> Response {
    status_only(StatusCode::NOT_FOUND)
}

fn internal() -> Response {
    status_only(StatusCode::INTERNAL_SERVER_ERROR)
}

// ================================================================ routing

const SLICE: [&str; 6] = ["users", "groups", "roles", "layers", "layerdatasources", "layerappearances"];

fn res_of(seg: &str) -> Option<Res> {
    Some(match seg {
        "users" => Res::Users,
        "groups" => Res::Groups,
        "roles" => Res::Roles,
        "layers" => Res::Layers,
        "layerdatasources" => Res::DataSources,
        "layerappearances" => Res::Appearances,
        _ => return None,
    })
}

pub async fn handle(State(st): State<Arc<AppState>>, req: Request) -> Response {
    let (parts, body) = req.into_parts();
    let method = parts.method.clone();
    let path = parts.uri.path().to_string();
    let query_str = parts.uri.query().unwrap_or("").to_string();
    let headers: HeaderMap = parts.headers.clone();

    let rest_path = match path.strip_prefix("/rest") {
        Some(p) if p.is_empty() || p.starts_with('/') => p.to_string(),
        _ => return not_found(),
    };
    let segs: Vec<String> = rest_path
        .split('/')
        .filter(|s| !s.is_empty())
        .map(|s| s.to_string())
        .collect();

    let body_bytes = match axum::body::to_bytes(body, 64 * 1024 * 1024).await {
        Ok(b) => b,
        Err(_) => return bad_request(),
    };

    let mut conn = match st.pool.acquire().await {
        Ok(c) => c,
        Err(_) => return internal(),
    };
    let auth_header = headers
        .get(header::AUTHORIZATION)
        .and_then(|v| v.to_str().ok());
    let principal = match auth::authenticate(&mut conn, auth_header).await {
        Ok(Some(p)) => p,
        Ok(None) => return unauthorized(),
        Err(_) => return internal(),
    };
    drop(conn);

    let query: Vec<(String, String)> = form_urlencoded::parse(query_str.as_bytes())
        .map(|(k, v)| (k.into_owned(), v.into_owned()))
        .collect();

    let slice_seg = segs.first().map(|s| s.as_str()).unwrap_or("");
    let in_slice = SLICE.contains(&slice_seg);
    // the security rules: slice paths need ROLE_USER, every other /rest path ROLE_ADMIN
    if in_slice {
        if !principal.is_user_or_admin() {
            return status_only(StatusCode::FORBIDDEN);
        }
    } else if !principal.is_admin {
        return status_only(StatusCode::FORBIDDEN);
    }

    let res = match res_of(slice_seg) {
        Some(r) if in_slice => r,
        _ => return not_found(),
    };
    let st = st.as_ref();
    match segs.len() {
        1 => match method {
            Method::GET => list(st, &principal, res, &query).await,
            Method::POST => create(st, &principal, res, &body_bytes).await,
            _ => status_only(StatusCode::METHOD_NOT_ALLOWED),
        },
        2 if segs[1] == "filter" => match method {
            Method::GET => filter(st, &principal, res, &query).await,
            _ => status_only(StatusCode::METHOD_NOT_ALLOWED),
        },
        2 => {
            let is_item_method = matches!(method, Method::GET | Method::PUT | Method::DELETE);
            if !is_item_method {
                return status_only(StatusCode::METHOD_NOT_ALLOWED);
            }
            let id = match segs[1].parse::<i32>() {
                Ok(i) => i,
                Err(_) => return bad_request(),
            };
            match method {
                Method::GET => get_one(st, &principal, res, id).await,
                Method::PUT => update(st, &principal, res, id, &body_bytes).await,
                _ => delete(st, &principal, res, id).await,
            }
        }
        3 if method == Method::GET
            && ((res == Res::Users && segs[2] == "userGroups")
                || (res == Res::Groups && segs[2] == "users")) =>
        {
            let id = match segs[1].parse::<i32>() {
                Ok(i) => i,
                Err(_) => return bad_request(),
            };
            if res == Res::Users {
                user_groups(st, &principal, id).await
            } else {
                group_users(st, &principal, id).await
            }
        }
        _ => not_found(),
    }
}

// ================================================================ lists

async fn list(st: &AppState, p: &Principal, res: Res, query: &[(String, String)]) -> Response {
    run_list(st, p, res, query, false).await
}

async fn filter(st: &AppState, p: &Principal, res: Res, query: &[(String, String)]) -> Response {
    run_list(st, p, res, query, true).await
}

async fn run_list(st: &AppState, p: &Principal, res: Res, query: &[(String, String)], is_filter: bool) -> Response {
    let restrict = restrict_fields(query, res);
    let conds = if is_filter {
        let c = filter_conditions(query, res);
        if c.is_empty() {
            return json_response(StatusCode::OK, &json!([]));
        }
        Some(c)
    } else {
        None
    };
    let mut conn = match st.pool.acquire().await {
        Ok(c) => c,
        Err(_) => return internal(),
    };
    let all = match load_all(&mut conn, res).await {
        Ok(v) => v,
        Err(_) => return internal(),
    };
    let matched: Vec<Ent> = match &conds {
        Some(c) => all.into_iter().filter(|e| matches_conditions(e, c)).collect(),
        None => all,
    };
    let kind = kind_entity_kind(res);
    let mut out = Vec::new();
    match restrict {
        None => {
            for e in matched {
                let id = match e.id() {
                    Some(i) => i,
                    None => continue,
                };
                match has_perm(&mut conn, p, kind, id, Perm::Read).await {
                    Ok(true) => out.push(e.to_json()),
                    Ok(false) => {}
                    Err(_) => return internal(),
                }
            }
        }
        Some(fields) => {
            // the abstract LayerDataSource cannot be instantiated for a projection
            if res == Res::DataSources {
                return if matched.is_empty() {
                    json_response(StatusCode::OK, &json!([]))
                } else {
                    internal()
                };
            }
            for e in matched {
                if bean_has_perm(p, kind, Perm::Read) {
                    out.push(restricted_json(res, &e, &fields));
                }
            }
        }
    }
    json_response(StatusCode::OK, &Value::Array(out))
}

// ================================================================ single entity

async fn get_one(st: &AppState, p: &Principal, res: Res, id: i32) -> Response {
    let mut conn = match st.pool.acquire().await {
        Ok(c) => c,
        Err(_) => return internal(),
    };
    let ent = match load_ent(&mut conn, res, id).await {
        Ok(Some(e)) => e,
        Ok(None) => return not_found(),
        Err(_) => return internal(),
    };
    match has_perm(&mut conn, p, kind_entity_kind(res), id, Perm::Read).await {
        Ok(true) => json_response(StatusCode::OK, &ent.to_json()),
        Ok(false) => not_found(),
        Err(_) => not_found(),
    }
}

/// Parses a request body as Jackson's `readValue`/`readTree` would see it.
/// `Ok(None)` for an empty body.
fn parse_body(body: &[u8]) -> Result<Option<Value>, ()> {
    let text = String::from_utf8_lossy(body);
    if text.trim().is_empty() {
        return Ok(None);
    }
    let mut stream = serde_json::Deserializer::from_str(&text).into_iter::<Value>();
    match stream.next() {
        Some(Ok(v)) => Ok(Some(v)),
        _ => Err(()),
    }
}

async fn create(st: &AppState, p: &Principal, res: Res, body: &[u8]) -> Response {
    // the abstract LayerDataSource cannot be bound from JSON
    if res == Res::DataSources {
        return bad_request();
    }
    let value = match parse_body(body) {
        Ok(Some(v)) => v,
        _ => return bad_request(),
    };
    let mut ent = new_ent(res);
    let parsed: JResult<()> = (|| {
        for (k, v) in obj(&value)? {
            if is_ignored_prop(k) {
                continue;
            }
            ent.apply(k, v)?;
        }
        Ok(())
    })();
    if parsed.is_err() || ent.id().is_some() {
        return bad_request();
    }
    // saveOrUpdate: CREATE is granted to no one but the super admin here
    if !p.is_admin {
        return bad_request();
    }
    let mut tx = match st.pool.begin().await {
        Ok(t) => t,
        Err(_) => return internal(),
    };
    let saved = save_new(&mut tx, &st.pool, &mut ent).await;
    if saved.is_err() {
        let _ = tx.rollback().await;
        return bad_request();
    }
    if tx.commit().await.is_err() {
        return bad_request();
    }
    json_response(StatusCode::CREATED, &ent.to_json())
}

async fn save_new(c: &mut Conn, pool: &PgPool, ent: &mut Ent) -> R<()> {
    match ent {
        Ent::User(u) => store::insert_user(c, pool, u).await,
        Ent::Group(g) => store::insert_group(c, pool, g).await,
        Ent::Role(r) => store::insert_role(c, pool, r).await,
        Ent::Layer(l) => store::save_layer_insert(c, pool, l).await,
        Ent::App(a) => store::save_appearance(c, pool, a, None, false, &Touched::default()).await,
        Ent::Ds(_) => Err(DbFail::Bad("cannot create a data source".into())),
    }
}

/// Writes a managed entity after its properties were bound.
async fn save_update(c: &mut Conn, pool: &PgPool, ent: &mut Ent, orig: &Ent, touched: &Touched) -> R<()> {
    match (ent, orig) {
        (Ent::User(u), _) => store::update_user(c, u, touched).await,
        (Ent::Group(g), _) => store::update_group(c, g, touched).await,
        (Ent::Role(r), _) => store::update_role(c, r).await,
        (Ent::Layer(l), Ent::Layer(o)) => {
            let orig_app = o.appearance.as_ref().and_then(|a| a.id);
            store::save_layer_update(c, pool, l, orig_app).await
        }
        (Ent::Ds(d), Ent::Ds(o)) => store::update_ds(c, pool, d, o, touched).await,
        (Ent::App(a), _) => store::save_appearance(c, pool, a, None, false, touched).await,
        _ => Err(DbFail::Bad("kind mismatch".into())),
    }
}

/// Jackson's `asInt()` on the payload's "id" node.
fn payload_int(v: &Value) -> i32 {
    match v {
        Value::Number(n) => n.as_i64().map(|i| i as i32).or_else(|| n.as_f64().map(|f| f as i32)).unwrap_or(0),
        Value::String(s) => s.trim().parse::<i32>().unwrap_or(0),
        Value::Bool(b) => i32::from(*b),
        _ => 0,
    }
}

async fn update(st: &AppState, p: &Principal, res: Res, id: i32, body: &[u8]) -> Response {
    // a malformed body fails in readTree (404); an empty one yields no node (400)
    let value = match parse_body(body) {
        Ok(Some(v)) => v,
        Ok(None) => return bad_request(),
        Err(()) => return not_found(),
    };
    let payload = match value.as_object().and_then(|m| m.get("id")) {
        Some(idv) => idv.clone(),
        None => return bad_request(),
    };
    if payload_int(&payload) != id {
        return bad_request();
    }
    let map: &Map<String, Value> = match value.as_object() {
        Some(m) => m,
        None => return bad_request(),
    };

    let mut tx = match st.pool.begin().await {
        Ok(t) => t,
        Err(_) => return internal(),
    };
    let orig = match load_ent(&mut tx, res, id).await {
        Ok(Some(e)) => e,
        Ok(None) => {
            let _ = tx.rollback().await;
            return not_found();
        }
        Err(_) => {
            let _ = tx.rollback().await;
            return not_found();
        }
    };
    let kind = kind_entity_kind(res);
    // findById (READ) and updatePartialWithJsonNode (UPDATE)
    let readable = has_perm(&mut tx, p, kind, id, Perm::Read).await;
    let updatable = has_perm(&mut tx, p, kind, id, Perm::Update).await;
    if !matches!(readable, Ok(true)) || !matches!(updatable, Ok(true)) {
        let _ = tx.rollback().await;
        return not_found();
    }

    let mut ent = orig.clone();
    let mut touched = Touched::default();
    let mut json_failed = false;
    for (k, v) in map {
        if is_ignored_prop(k) {
            continue;
        }
        if ent.apply(k, v).is_err() {
            // Jackson fails midway: the properties bound so far are still flushed
            json_failed = true;
            break;
        }
        if let Some(ck) = collection_key(k) {
            touched.0.insert(ck);
        }
    }

    let saved = save_update(&mut tx, &st.pool, &mut ent, &orig, &touched).await;
    if saved.is_err() {
        let _ = tx.rollback().await;
        return not_found();
    }
    if tx.commit().await.is_err() {
        return not_found();
    }
    if json_failed {
        return not_found();
    }
    json_response(StatusCode::OK, &ent.to_json())
}

async fn delete(st: &AppState, p: &Principal, res: Res, id: i32) -> Response {
    let mut tx = match st.pool.begin().await {
        Ok(t) => t,
        Err(_) => return internal(),
    };
    let ent = match load_ent(&mut tx, res, id).await {
        Ok(Some(e)) => e,
        _ => {
            let _ = tx.rollback().await;
            return not_found();
        }
    };
    let kind = kind_entity_kind(res);
    let readable = has_perm(&mut tx, p, kind, id, Perm::Read).await;
    let deletable = has_perm(&mut tx, p, kind, id, Perm::Delete).await;
    if !matches!(readable, Ok(true)) || !matches!(deletable, Ok(true)) {
        let _ = tx.rollback().await;
        return not_found();
    }
    let done = delete_ent(&mut tx, p, &ent, id).await;
    if done.is_err() {
        let _ = tx.rollback().await;
        return not_found();
    }
    if tx.commit().await.is_err() {
        return not_found();
    }
    status_only(StatusCode::NO_CONTENT)
}

async fn delete_ent(c: &mut Conn, p: &Principal, ent: &Ent, id: i32) -> R<()> {
    match ent {
        Ent::User(_) => store::delete_user(c, id).await,
        Ent::Group(_) => store::delete_group(c, id).await,
        Ent::Role(_) => store::delete_role(c, id).await,
        Ent::App(_) => store::delete_appearance(c, id).await,
        Ent::Layer(_) => {
            // LayerService.delete: the layer leaves every map that contains it;
            // saving such a map needs UPDATE on the map
            let pool_less = &mut *c;
            for map_id in store::maps_with_layer(pool_less, id).await? {
                if !p.is_admin {
                    let ok = has_perm(c, p, Kind::AlwaysRead, map_id, Perm::Update).await?;
                    if !ok {
                        return Err(DbFail::Bad("access denied on map".into()));
                    }
                }
                store::remove_layer_from_map(c, map_id, id).await?;
            }
            store::delete_layer(c, id).await
        }
        Ent::Ds(d) => {
            let wmts_tg = match &d.kind {
                DsKind::Wmts(w) => w.tile_grid.as_ref().and_then(|t| t.id),
                _ => None,
            };
            store::delete_ds(c, id, wmts_tg, &d.kind).await
        }
    }
}

// ================================================================ sub-resources

async fn user_groups(st: &AppState, p: &Principal, id: i32) -> Response {
    let mut conn = match st.pool.acquire().await {
        Ok(c) => c,
        Err(_) => return internal(),
    };
    // UserService.getGroupsOfUser: the user is loaded without a READ check
    let user = match store::load_user(&mut conn, id).await {
        Ok(Some(u)) => u,
        Ok(None) => return not_found(),
        Err(_) => return internal(),
    };
    let mut out = Vec::new();
    for gid in user.user_groups.unwrap_or_default().into_iter().flatten() {
        let g = match store::load_group(&mut conn, gid).await {
            Ok(Some(g)) => g,
            Ok(None) => continue,
            Err(_) => return internal(),
        };
        match has_perm(&mut conn, p, Kind::Group, gid, Perm::Read).await {
            Ok(true) => out.push(g.to_json()),
            Ok(false) => {}
            Err(_) => return internal(),
        }
    }
    json_response(StatusCode::OK, &Value::Array(out))
}

async fn group_users(st: &AppState, p: &Principal, id: i32) -> Response {
    let mut conn = match st.pool.acquire().await {
        Ok(c) => c,
        Err(_) => return internal(),
    };
    // UserGroupService.getUsersOfGroup: the group is loaded without a READ check
    let group = match store::load_group(&mut conn, id).await {
        Ok(Some(g)) => g,
        Ok(None) => return not_found(),
        Err(_) => return internal(),
    };
    let mut out = Vec::new();
    for u in group.members.unwrap_or_default() {
        let uid = match u.id {
            Some(i) => i,
            None => continue,
        };
        match has_perm(&mut conn, p, Kind::User, uid, Perm::Read).await {
            Ok(true) => out.push(u.to_json()),
            Ok(false) => {}
            Err(_) => return internal(),
        }
    }
    json_response(StatusCode::OK, &Value::Array(out))
}

