//! SHOGun REST slice (users, groups, roles, layers, layer data sources and
//! layer appearances) on the original's PostgreSQL schema.

mod auth;
mod json;
mod model;
mod rest;
mod store;

use std::sync::Arc;

use axum::Router;
use sqlx::postgres::PgPoolOptions;

#[tokio::main]
async fn main() {
    let url = std::env::var("DATABASE_URL").expect("DATABASE_URL must be set");
    let port: u16 = std::env::var("PORT")
        .ok()
        .and_then(|p| p.parse().ok())
        .unwrap_or(8080);

    let pool = PgPoolOptions::new()
        .max_connections(16)
        .connect(&url)
        .await
        .expect("cannot connect to the database");

    let state = Arc::new(rest::AppState { pool });
    let app = Router::new().fallback(rest::handle).with_state(state);

    let listener = tokio::net::TcpListener::bind(("0.0.0.0", port))
        .await
        .expect("cannot bind the port");
    axum::serve(listener, app).await.expect("server failed");
}

