#!/usr/bin/env python3
"""Replays scenarios against the original (ref, :8081) and the port (:8082).

For every scenario both databases are reset to the same seed, the same HTTP
requests are sent to both services, and the responses (status, normalised JSON)
and the slice tables afterwards are compared. created/modified are ignored.
"""
import base64
import json
import subprocess
import sys
import urllib.error
import urllib.request

REF = ("http://localhost:8081", "ref")
PORT = ("http://localhost:8082", "port")

TABLES = [
    "persons", "users", "roles", "usergroups", "user_usergroup", "users_roles",
    "usergroups_roles", "layers", "layerappearances", "layerappearances_properties",
    "layerdatasources", "imagewmslayerdatasources", "tilewmslayerdatasources",
    "wfslayerdatasources", "wmtslayerdatasources", "wmtslayerdatasources_urls",
    "xyzlayerdatasources", "xyzlayerdatasrc_resolution", "extents", "tilegrids",
    "tilegrid_resolution", "wmtstilegrids", "wmtstilegrids_matrixids",
    "permissioncollections", "permissioncollections_permissions", "userpermissions",
    "grouppermissions", "maps_layers", "hibernate_sequences", "maps", "modules",
]
SKIP_COLS = {"created", "modified"}


def sh(args):
    return subprocess.run(args, capture_output=True, text=True, check=True).stdout


def reset(db):
    subprocess.run(["/work/harness/reset_db.sh", db], check=True)


def snapshot(db):
    cols = sh(["psql", "-d", db, "-At", "-F", "\x1f", "-c",
               "SELECT table_name, column_name FROM information_schema.columns "
               "WHERE table_schema='public' ORDER BY table_name, ordinal_position"])
    per = {}
    for line in cols.splitlines():
        t, c = line.split("\x1f")
        per.setdefault(t, []).append(c)
    out = {}
    for t in TABLES:
        if t not in per:
            continue
        cl = [c for c in per[t] if c not in SKIP_COLS]
        q = "SELECT %s FROM %s" % (", ".join('"%s"' % c for c in cl), t)
        rows = sh(["psql", "-d", db, "-At", "-F", "|", "-c", q]).splitlines()
        out[t] = sorted(rows)
    return out


def norm(v):
    if isinstance(v, dict):
        return {k: norm(x) for k, x in v.items() if k not in SKIP_COLS}
    if isinstance(v, list):
        items = [norm(x) for x in v]
        return sorted(items, key=lambda x: json.dumps(x, sort_keys=True))
    if isinstance(v, float) and v == int(v) and abs(v) < 1e15:
        return float(v)
    return v


def request(base, step):
    method, path, auth, body, headers = step
    url = base + path
    data = None
    if body is not None:
        data = body.encode("utf-8") if isinstance(body, str) else body
    req = urllib.request.Request(url, data=data, method=method)
    if auth:
        tok = base64.b64encode(("%s:%s" % auth).encode()).decode()
        req.add_header("Authorization", "Basic " + tok)
    for k, v in (headers or {}).items():
        req.add_header(k, v)
    if body is not None and "Content-Type" not in (headers or {}):
        req.add_header("Content-Type", "application/json")
    try:
        with urllib.request.urlopen(req, timeout=20) as r:
            status, raw, hdr = r.status, r.read(), r.headers
    except urllib.error.HTTPError as e:
        status, raw, hdr = e.code, e.read(), e.headers
    text = raw.decode("utf-8", "replace")
    parsed = None
    if text.strip():
        try:
            parsed = json.loads(text)
        except ValueError:
            parsed = "<non-json:%d bytes>" % len(text)
    www = hdr.get("WWW-Authenticate")
    return status, parsed, www


def run_scenario(name, steps):
    results = {}
    for base, db in (REF, PORT):
        reset(db)
        res = []
        for st in steps:
            status, parsed, www = request(base, st)
            res.append((status, norm(parsed) if not isinstance(parsed, str) else parsed,
                        www is not None))
        results[db] = (res, snapshot(db))
    ok = True
    report = []
    ref_res, ref_db = results["ref"]
    port_res, port_db = results["port"]
    for i, (a, b) in enumerate(zip(ref_res, port_res)):
        step = steps[i]
        same_status = a[0] == b[0]
        same_body = a[1] == b[1]
        same_www = a[2] == b[2]
        if not (same_status and same_body and same_www):
            ok = False
            report.append("  step %d %s %s: status ref=%s port=%s" % (i, step[0], step[1], a[0], b[0]))
            if not same_body:
                report.append("     body ref =%s" % json.dumps(a[1], sort_keys=True)[:700])
                report.append("     body port=%s" % json.dumps(b[1], sort_keys=True)[:700])
            if not same_www:
                report.append("     WWW-Authenticate ref=%s port=%s" % (a[2], b[2]))
    for t in TABLES:
        if ref_db.get(t) != port_db.get(t):
            ok = False
            r_set = set(ref_db.get(t, []))
            p_set = set(port_db.get(t, []))
            report.append("  table %s differs: only-ref=%s only-port=%s" % (
                t, sorted(r_set - p_set)[:5], sorted(p_set - r_set)[:5]))
    status = "PASS" if ok else "FAIL"
    print("%s %s" % (status, name))
    for line in report:
        print(line)
    return ok


def main(only=None):
    sys.path.insert(0, "/work/harness")
    from scenarios import SCENARIOS
    passed = failed = 0
    for name, steps in SCENARIOS:
        if only and only not in name:
            continue
        if run_scenario(name, steps):
            passed += 1
        else:
            failed += 1
    print("passed=%d failed=%d" % (passed, failed))


if __name__ == "__main__":
    main(sys.argv[1] if len(sys.argv) > 1 else None)

