async fn insert_group_rows(c: &mut Conn, g: &UserGroup) -> R<()> {
    if let Some(members) = &g.members {
        let mut ids = Vec::new();
        for m in members {
            ids.push(check_id(m.id)?);
        }
        let ids = dedupe_by_id(ids.into_iter().map(|i| (Some(i), i)).collect())?;
        for uid in ids {
            sqlx::query("INSERT INTO user_usergroup (usergroup_id, user_id) VALUES ($1, $2)")
                .bind(g.id)
                .bind(uid)
                .execute(&mut *c)
                .await?;
        }
    }
    if let Some(roles) = &g.roles {
        let mut ids = Vec::new();
        for r in roles {
            ids.push(check_id(r.id)?);
        }
        let ids = dedupe_by_id(ids.into_iter().map(|i| (Some(i), i)).collect())?;
        for rid in ids {
            sqlx::query("INSERT INTO usergroups_roles (usergroup_id, role_id) VALUES ($1, $2)")
                .bind(g.id)
                .bind(rid)
                .execute(&mut *c)
                .await?;
        }
    }
    Ok(())
}

