pub async fn update_group(c: &mut Conn, g: &UserGroup, touched: &Touched) -> R<()> {
    let id = check_id(g.id)?;
    let owner_id = match &g.owner {
        Some(o) => Some(check_id(o.id)?),
        None => None,
    };
    let res = sqlx::query(
        "UPDATE usergroups SET modified = localtimestamp, name = $2, owner_id = $3 WHERE id = $1",
    )
    .bind(id)
    .bind(&g.name)
    .bind(owner_id)
    .execute(&mut *c)
    .await?;
    expect_one(res).await?;
    if touched.has("members") {
        sqlx::query("DELETE FROM user_usergroup WHERE usergroup_id = $1")
            .bind(id)
            .execute(&mut *c)
            .await?;
    }
    if touched.has("roles") {
        sqlx::query("DELETE FROM usergroups_roles WHERE usergroup_id = $1")
            .bind(id)
            .execute(&mut *c)
            .await?;
    }
    let tmp = UserGroup {
        id: Some(id),
        name: None,
        owner: None,
        members: if touched.has("members") { g.members.clone() } else { None },
        roles: if touched.has("roles") { g.roles.clone() } else { None },
    };
    insert_group_rows(c, &tmp).await
}

