//! Database access for the slice. Reproduces what Hibernate does on the schema:
//! ids from the `hibernate_sequences` table generator, JOINED inheritance across
//! the subclass tables, cascades of the mapped associations, and replacement of
//! collections (delete the owner's rows, insert the new ones).

use std::collections::HashSet;

use chrono::NaiveDate;
use serde_json::Value;
use sqlx::{PgConnection, PgPool, Row};

use crate::json::{JErr, property_from_db, property_to_db};
use crate::model::*;

pub type Conn = PgConnection;

/// Why a database operation failed. `Bad` is a logical failure (a transient
/// object, a stale row, a NonUniqueObjectException), `Sql` a database error.
#[derive(Debug)]
pub enum DbFail {
    Sql(sqlx::Error),
    Bad(String),
}

impl From<sqlx::Error> for DbFail {
    fn from(e: sqlx::Error) -> Self {
        DbFail::Sql(e)
    }
}

impl From<JErr> for DbFail {
    fn from(e: JErr) -> Self {
        DbFail::Bad(e.0)
    }
}

pub type R<T> = Result<T, DbFail>;

fn bad<T>(msg: impl Into<String>) -> R<T> {
    Err(DbFail::Bad(msg.into()))
}

/// Which collections a top-level update replaces, i.e. the JSON properties it
/// carried. Nested (cascaded) objects are always written in full.
#[derive(Default, Clone)]
pub struct Touched(pub HashSet<&'static str>);

impl Touched {
    pub fn has(&self, k: &str) -> bool {
        self.0.contains(k)
    }
}

/// Allocates an id the way Hibernate's table generator does, in its own
/// transaction (so an id stays used even if the request is rolled back).
pub async fn next_id(pool: &PgPool) -> R<i32> {
    let v: i64 = sqlx::query_scalar(
        "UPDATE hibernate_sequences SET next_val = next_val + 1 \
         WHERE sequence_name = 'default' RETURNING next_val",
    )
    .fetch_one(pool)
    .await?;
    Ok(v as i32)
}

fn dedupe_by_id<T>(v: Vec<(Option<i32>, T)>) -> R<Vec<T>> {
    // A HashSet of detached objects: equal ids collapse onto the first one.
    let mut seen = HashSet::new();
    let mut out = Vec::new();
    for (id, t) in v {
        let id = match id {
            Some(i) => i,
            None => return bad("transient object in collection"),
        };
        if seen.insert(id) {
            out.push(t);
        }
    }
    Ok(out)
}

// ================================================================ Java double

const JAVA_DOUBLE_PREFIX: [u8; 76] = [
    0xac, 0xed, 0x00, 0x05, 0x73, 0x72, 0x00, 0x10, 0x6a, 0x61, 0x76, 0x61, 0x2e, 0x6c, 0x61,
    0x6e, 0x67, 0x2e, 0x44, 0x6f, 0x75, 0x62, 0x6c, 0x65, 0x80, 0xb3, 0xc2, 0x4a, 0x29, 0x6b,
    0xfb, 0x04, 0x02, 0x00, 0x01, 0x44, 0x00, 0x05, 0x76, 0x61, 0x6c, 0x75, 0x65, 0x78, 0x72,
    0x00, 0x10, 0x6a, 0x61, 0x76, 0x61, 0x2e, 0x6c, 0x61, 0x6e, 0x67, 0x2e, 0x4e, 0x75, 0x6d,
    0x62, 0x65, 0x72, 0x86, 0xac, 0x95, 0x1d, 0x0b, 0x94, 0xe0, 0x8b, 0x02, 0x00, 0x00, 0x78,
    0x70,
];

/// Java-serialized `java.lang.Double` (the XYZ source's resolutions are stored so).
fn encode_java_double(d: f64) -> Vec<u8> {
    let mut v = JAVA_DOUBLE_PREFIX.to_vec();
    v.extend_from_slice(&d.to_bits().to_be_bytes());
    v
}

fn decode_java_double(b: &[u8]) -> Option<f64> {
    if b.len() < 8 {
        return None;
    }
    let mut arr = [0u8; 8];
    arr.copy_from_slice(&b[b.len() - 8..]);
    Some(f64::from_bits(u64::from_be_bytes(arr)))
}

// ================================================================ Loaders

fn point_of(x: Option<f64>, y: Option<f64>) -> Option<Point> {
    if x.is_none() && y.is_none() {
        None
    } else {
        Some(Point {
            x: x.unwrap_or(0.0),
            y: y.unwrap_or(0.0),
        })
    }
}

pub async fn load_role(c: &mut Conn, id: i32) -> R<Option<Role>> {
    let row = sqlx::query("SELECT id, name, description FROM roles WHERE id = $1")
        .bind(id)
        .fetch_optional(&mut *c)
        .await?;
    Ok(row.map(|r| Role {
        id: r.get("id"),
        name: r.get("name"),
        description: r.get("description"),
    }))
}

pub async fn all_ids(c: &mut Conn, table: &'static str) -> R<Vec<i32>> {
    let sql = match table {
        "users" => "SELECT id FROM users ORDER BY id",
        "usergroups" => "SELECT id FROM usergroups ORDER BY id",
        "roles" => "SELECT id FROM roles ORDER BY id",
        "layers" => "SELECT id FROM layers ORDER BY id",
        "layerdatasources" => "SELECT id FROM layerdatasources ORDER BY id",
        "layerappearances" => "SELECT id FROM layerappearances ORDER BY id",
        _ => return bad("unknown table"),
    };
    let rows = sqlx::query_scalar::<_, i32>(sql).fetch_all(&mut *c).await?;
    Ok(rows)
}

pub async fn load_user(c: &mut Conn, id: i32) -> R<Option<User>> {
    let row = sqlx::query(
        "SELECT p.id, p.firstname, p.lastname, p.email, p.birthday, p.language, \
                u.accountname, u.password, u.active \
         FROM persons p JOIN users u ON u.id = p.id WHERE p.id = $1",
    )
    .bind(id)
    .fetch_optional(&mut *c)
    .await?;
    let row = match row {
        Some(r) => r,
        None => return Ok(None),
    };
    let birthday: Option<NaiveDate> = row.try_get("birthday")?;
    let roles = sqlx::query(
        "SELECT r.id, r.name, r.description FROM users_roles ur \
         JOIN roles r ON r.id = ur.role_id WHERE ur.user_id = $1 ORDER BY r.id",
    )
    .bind(id)
    .fetch_all(&mut *c)
    .await?
    .into_iter()
    .map(|r| Role {
        id: r.get("id"),
        name: r.get("name"),
        description: r.get("description"),
    })
    .collect();
    let groups: Vec<Option<i32>> = sqlx::query_scalar::<_, i32>(
        "SELECT usergroup_id FROM user_usergroup WHERE user_id = $1 ORDER BY usergroup_id",
    )
    .bind(id)
    .fetch_all(&mut *c)
    .await?
    .into_iter()
    .map(Some)
    .collect();
    Ok(Some(User {
        id: row.get("id"),
        first_name: row.get("firstname"),
        last_name: row.get("lastname"),
        email: row.get("email"),
        birthday,
        language: row.get("language"),
        account_name: row.get("accountname"),
        password: row.get("password"),
        active: row.get("active"),
        roles: Some(roles),
        user_groups: Some(groups),
    }))
}

pub async fn load_group(c: &mut Conn, id: i32) -> R<Option<UserGroup>> {
    let row = sqlx::query("SELECT id, name, owner_id FROM usergroups WHERE id = $1")
        .bind(id)
        .fetch_optional(&mut *c)
        .await?;
    let row = match row {
        Some(r) => r,
        None => return Ok(None),
    };
    let owner_id: Option<i32> = row.get("owner_id");
    let owner = match owner_id {
        Some(o) => load_user(c, o).await?.map(Box::new),
        None => None,
    };
    let member_ids: Vec<i32> = sqlx::query_scalar(
        "SELECT user_id FROM user_usergroup WHERE usergroup_id = $1 ORDER BY user_id",
    )
    .bind(id)
    .fetch_all(&mut *c)
    .await?;
    let mut members = Vec::new();
    for m in member_ids {
        if let Some(u) = load_user(c, m).await? {
            members.push(u);
        }
    }
    let roles = sqlx::query(
        "SELECT r.id, r.name, r.description FROM usergroups_roles gr \
         JOIN roles r ON r.id = gr.role_id WHERE gr.usergroup_id = $1 ORDER BY r.id",
    )
    .bind(id)
    .fetch_all(&mut *c)
    .await?
    .into_iter()
    .map(|r| Role {
        id: r.get("id"),
        name: r.get("name"),
        description: r.get("description"),
    })
    .collect();
    Ok(Some(UserGroup {
        id: row.get("id"),
        name: row.get("name"),
        owner,
        members: Some(members),
        roles: Some(roles),
    }))
}

pub async fn load_appearance(c: &mut Conn, id: i32) -> R<Option<Appearance>> {
    let row = sqlx::query(
        "SELECT id, attribution, hoverable, clickable, hovertemplate, name, \
                maxresolution, minresolution, opacity, visible \
         FROM layerappearances WHERE id = $1",
    )
    .bind(id)
    .fetch_optional(&mut *c)
    .await?;
    let row = match row {
        Some(r) => r,
        None => return Ok(None),
    };
    let props: Vec<(String, Value)> = sqlx::query(
        "SELECT property, value FROM layerappearances_properties WHERE appearance_id = $1 \
         ORDER BY property",
    )
    .bind(id)
    .fetch_all(&mut *c)
    .await?
    .into_iter()
    .filter_map(|r| {
        let k: String = r.get("property");
        let v: Option<String> = r.get("value");
        v.map(|v| (k, property_from_db(&v)))
    })
    .collect();
    Ok(Some(Appearance {
        id: row.get("id"),
        attribution: row.get("attribution"),
        hoverable: row.get("hoverable"),
        clickable: row.get("clickable"),
        hover_template: row.get("hovertemplate"),
        properties: Some(props),
        name: row.get("name"),
        max_resolution: row.get("maxresolution"),
        min_resolution: row.get("minresolution"),
        opacity: row.get("opacity"),
        visible: row.get("visible"),
    }))
}

pub async fn load_layer(c: &mut Conn, id: i32) -> R<Option<Layer>> {
    let row = sqlx::query(
        "SELECT id, name, description, appearance_id, source_id FROM layers WHERE id = $1",
    )
    .bind(id)
    .fetch_optional(&mut *c)
    .await?;
    let row = match row {
        Some(r) => r,
        None => return Ok(None),
    };
    let app_id: Option<i32> = row.get("appearance_id");
    let src_id: Option<i32> = row.get("source_id");
    let appearance = match app_id {
        Some(a) => load_appearance(c, a).await?.map(Box::new),
        None => None,
    };
    let source = match src_id {
        Some(s) => load_ds(c, s).await?.map(Box::new),
        None => None,
    };
    Ok(Some(Layer {
        id: row.get("id"),
        name: row.get("name"),
        description: row.get("description"),
        source,
        appearance,
    }))
}

pub async fn load_extent(c: &mut Conn, id: i32) -> R<Option<Extent>> {
    let row = sqlx::query(
        "SELECT id, lowerleft_x, lowerleft_y, upperright_x, upperright_y FROM extents WHERE id = $1",
    )
    .bind(id)
    .fetch_optional(&mut *c)
    .await?;
    Ok(row.map(|r| Extent {
        id: r.get("id"),
        lower_left: point_of(r.get("lowerleft_x"), r.get("lowerleft_y")),
        upper_right: point_of(r.get("upperright_x"), r.get("upperright_y")),
    }))
}

async fn load_tile_grid(c: &mut Conn, id: i32) -> R<Option<TileGrid>> {
    let row = sqlx::query(
        "SELECT t.id, t.type, t.tilegridorigin_x, t.tilegridorigin_y, t.tilesize, \
                t.tilegridextent_id, (w.id IS NOT NULL) AS is_wmts \
         FROM tilegrids t LEFT JOIN wmtstilegrids w ON w.id = t.id WHERE t.id = $1",
    )
    .bind(id)
    .fetch_optional(&mut *c)
    .await?;
    let row = match row {
        Some(r) => r,
        None => return Ok(None),
    };
    let wmts: bool = row.get("is_wmts");
    let ext_id: Option<i32> = row.get("tilegridextent_id");
    let extent = match ext_id {
        Some(e) => load_extent(c, e).await?,
        None => None,
    };
    let resolutions: Vec<f64> = sqlx::query_scalar::<_, Option<f64>>(
        "SELECT resolution FROM tilegrid_resolution WHERE tilegrid_id = $1 ORDER BY idx",
    )
    .bind(id)
    .fetch_all(&mut *c)
    .await?
    .into_iter()
    .flatten()
    .collect();
    let matrix_ids = if wmts {
        Some(
            sqlx::query_scalar::<_, Option<String>>(
                "SELECT matrixids FROM wmtstilegrids_matrixids WHERE wmtstilegrids_id = $1",
            )
            .bind(id)
            .fetch_all(&mut *c)
            .await?
            .into_iter()
            .flatten()
            .collect(),
        )
    } else {
        None
    };
    Ok(Some(TileGrid {
        id: row.get("id"),
        type_: row.get("type"),
        origin: point_of(row.get("tilegridorigin_x"), row.get("tilegridorigin_y")),
        extent,
        tile_size: row.get("tilesize"),
        resolutions: Some(resolutions),
        matrix_ids,
        wmts,
    }))
}

pub async fn load_ds(c: &mut Conn, id: i32) -> R<Option<DataSource>> {
    let row = sqlx::query(
        "SELECT l.id, l.name, l.type, l.url, l.format, \
                (i.id IS NOT NULL) AS has_img, i.width, i.height, i.version AS img_version, \
                i.layernames, i.layerstyles, i.requestablebypath, i.customrequestpath, \
                (t.id IS NOT NULL) AS has_tile, t.request_with_tiled, t.tilegrid_id AS tile_tg, \
                (w.id IS NOT NULL) AS has_wfs, w.version AS wfs_version, w.typename, w.typenames, \
                (m.id IS NOT NULL) AS has_wmts, m.capabilitiesurl, m.matrixset, m.projection, \
                m.requestencoding, m.wmtslayer, m.wmtsstyle, m.tilegrid_id AS wmts_tg, \
                (x.id IS NOT NULL) AS has_xyz, x.center_x, x.center_y, x.tilesize AS xyz_size, \
                x.extent_id AS xyz_extent \
         FROM layerdatasources l \
         LEFT JOIN imagewmslayerdatasources i ON i.id = l.id \
         LEFT JOIN tilewmslayerdatasources t ON t.id = l.id \
         LEFT JOIN wfslayerdatasources w ON w.id = l.id \
         LEFT JOIN wmtslayerdatasources m ON m.id = l.id \
         LEFT JOIN xyzlayerdatasources x ON x.id = l.id \
         WHERE l.id = $1",
    )
    .bind(id)
    .fetch_optional(&mut *c)
    .await?;
    let row = match row {
        Some(r) => r,
        None => return Ok(None),
    };
    let image = ImageWms {
        width: row.try_get::<Option<i32>, _>("width")?.unwrap_or(0),
        height: row.try_get::<Option<i32>, _>("height")?.unwrap_or(0),
        version: row.try_get("img_version")?,
        layer_names: row.try_get("layernames")?,
        layer_styles: row.try_get("layerstyles")?,
        requestable_by_path: row.try_get("requestablebypath")?,
        custom_request_path: row.try_get("customrequestpath")?,
    };
    let kind = if row.get::<bool, _>("has_tile") {
        let tg_id: Option<i32> = row.get("tile_tg");
        let tile_grid = match tg_id {
            Some(t) => load_tile_grid(c, t).await?,
            None => None,
        };
        DsKind::TileWms(TileWms {
            image,
            tile_grid,
            request_with_tiled: row.get("request_with_tiled"),
        })
    } else if row.get::<bool, _>("has_img") {
        DsKind::ImageWms(image)
    } else if row.get::<bool, _>("has_wfs") {
        DsKind::Wfs(Wfs {
            version: row.get("wfs_version"),
            type_name: row.get("typename"),
            type_names: row.get("typenames"),
        })
    } else if row.get::<bool, _>("has_wmts") {
        let tg_id: Option<i32> = row.get("wmts_tg");
        let tile_grid = match tg_id {
            Some(t) => load_tile_grid(c, t).await?,
            None => None,
        };
        let urls: Vec<String> = sqlx::query_scalar::<_, Option<String>>(
            "SELECT urls FROM wmtslayerdatasources_urls WHERE wmtslayerdatasources_id = $1",
        )
        .bind(id)
        .fetch_all(&mut *c)
        .await?
        .into_iter()
        .flatten()
        .collect();
        DsKind::Wmts(Wmts {
            tile_grid,
            urls: Some(urls),
            wmts_layer: row.get("wmtslayer"),
            wmts_style: row.get("wmtsstyle"),
            projection: row.get("projection"),
            matrix_set: row.get("matrixset"),
            request_encoding: row.get("requestencoding"),
            capabilities_url: row.get("capabilitiesurl"),
        })
    } else if row.get::<bool, _>("has_xyz") {
        let ext_id: Option<i32> = row.get("xyz_extent");
        let extent = match ext_id {
            Some(e) => load_extent(c, e).await?,
            None => None,
        };
        let resolutions: Vec<f64> = sqlx::query_scalar::<_, Vec<u8>>(
            "SELECT resolution FROM xyzlayerdatasrc_resolution \
             WHERE xyzlayerdatasrc_id = $1 ORDER BY idx",
        )
        .bind(id)
        .fetch_all(&mut *c)
        .await?
        .iter()
        .filter_map(|b| decode_java_double(b))
        .collect();
        DsKind::Xyz(Xyz {
            center: point_of(row.get("center_x"), row.get("center_y")),
            extent,
            resolutions: Some(resolutions),
            tile_size: row.get("xyz_size"),
        })
    } else {
        return bad("layer data source without a subtype row");
    };
    Ok(Some(DataSource {
        id: row.get("id"),
        name: row.get("name"),
        type_: row.get("type"),
        url: row.get("url"),
        format: row.get("format"),
        kind,
    }))
}

// ================================================================ Savers

fn check_id(id: Option<i32>) -> R<i32> {
    match id {
        Some(i) => Ok(i),
        None => bad("object without id (transient)"),
    }
}

async fn expect_one(res: sqlx::postgres::PgQueryResult) -> R<()> {
    if res.rows_affected() == 1 {
        Ok(())
    } else {
        bad("stale row")
    }
}

pub async fn insert_role(c: &mut Conn, pool: &PgPool, r: &mut Role) -> R<()> {
    let id = next_id(pool).await?;
    r.id = Some(id);
    sqlx::query(
        "INSERT INTO roles (id, created, modified, description, name) \
         VALUES ($1, localtimestamp, localtimestamp, $2, $3)",
    )
    .bind(id)
    .bind(&r.description)
    .bind(&r.name)
    .execute(&mut *c)
    .await?;
    Ok(())
}

pub async fn update_role(c: &mut Conn, r: &Role) -> R<()> {
    let id = check_id(r.id)?;
    let res = sqlx::query(
        "UPDATE roles SET modified = localtimestamp, description = $2, name = $3 WHERE id = $1",
    )
    .bind(id)
    .bind(&r.description)
    .bind(&r.name)
    .execute(&mut *c)
    .await?;
    expect_one(res).await
}

pub async fn delete_role(c: &mut Conn, id: i32) -> R<()> {
    delete_perm_rows(c, id).await?;
    let res = sqlx::query("DELETE FROM roles WHERE id = $1")
        .bind(id)
        .execute(&mut *c)
        .await?;
    expect_one(res).await
}

