//! Domain objects of the slice, mirroring the original's entity classes.
//!
//! Every field is an `Option` (or a collection that can be null) where the
//! original's Java object can hold null. `apply` binds one JSON property the way
//! Jackson binds it onto the object; `to_json` writes the object the way
//! Jackson serializes it (the library's getters, with the library's @JsonIgnore
//! and identity annotations).

use chrono::NaiveDate;
use serde_json::{Map, Value, json};

use crate::json::*;

/// JSON properties that Jackson ignores on the slice's entities.
pub fn is_ignored_prop(k: &str) -> bool {
    matches!(k, "created" | "modified" | "userPermissions" | "groupPermissions")
}

/// A `HashSet` of detached objects: an element equal to an earlier one (by the
/// library's `equals`, which ignores the id) is dropped; the first one stays.
fn dedupe_by<T>(items: Vec<T>, key: impl Fn(&T) -> String) -> Vec<T> {
    let mut seen = std::collections::HashSet::new();
    items.into_iter().filter(|t| seen.insert(key(t))).collect()
}

/// `User.equals`: the person and account fields, not id, roles or groups.
fn user_key(u: &User) -> String {
    json!([
        u.first_name, u.last_name, u.email,
        u.birthday.map(|d| d.format("%Y-%m-%d").to_string()),
        u.language, u.account_name, u.password, u.active
    ])
    .to_string()
}

/// `Role.equals`: name and description.
fn role_key(r: &Role) -> String {
    json!([r.name, r.description]).to_string()
}

fn null_or<T>(o: &Option<T>, f: impl Fn(&T) -> Value) -> Value {
    match o {
        Some(v) => f(v),
        None => Value::Null,
    }
}

fn opt_str(o: &Option<String>) -> Value {
    null_or(o, |s| Value::String(s.clone()))
}

fn opt_i32(o: &Option<i32>) -> Value {
    null_or(o, |i| Value::from(*i))
}

fn opt_bool(o: &Option<bool>) -> Value {
    null_or(o, |b| Value::Bool(*b))
}

fn opt_f64(o: &Option<f64>) -> Value {
    null_or(o, |d| f64_val(*d))
}

fn vec_json<T>(o: &Option<Vec<T>>, f: impl Fn(&T) -> Value) -> Value {
    match o {
        Some(v) => Value::Array(v.iter().map(f).collect()),
        None => Value::Null,
    }
}

// ---------------------------------------------------------------- Point / Extent

#[derive(Clone, Debug, Default, PartialEq)]
pub struct Point {
    pub x: f64,
    pub y: f64,
}

impl Point {
    pub fn from_json(v: &Value) -> JResult<Option<Point>> {
        match v {
            Value::Null => Ok(None),
            Value::Object(m) => {
                let mut p = Point::default();
                for (k, val) in m {
                    match k.as_str() {
                        "x" => p.x = f64_opt(val)?.unwrap_or(0.0),
                        "y" => p.y = f64_opt(val)?.unwrap_or(0.0),
                        _ => return err("unknown point property"),
                    }
                }
                Ok(Some(p))
            }
            _ => err("expected a point"),
        }
    }

    pub fn to_json(&self) -> Value {
        json!({ "x": f64_val(self.x), "y": f64_val(self.y) })
    }
}

fn point_json(o: &Option<Point>) -> Value {
    null_or(o, |p| p.to_json())
}

#[derive(Clone, Debug, Default)]
pub struct Extent {
    pub id: Option<i32>,
    pub lower_left: Option<Point>,
    pub upper_right: Option<Point>,
}

impl Extent {
    pub fn apply(&mut self, k: &str, v: &Value) -> JResult<()> {
        match k {
            "id" => self.id = int_opt(v)?,
            "lowerLeft" => self.lower_left = Point::from_json(v)?,
            "upperRight" => self.upper_right = Point::from_json(v)?,
            _ => return err(format!("unknown property {k} on Extent")),
        }
        Ok(())
    }

    pub fn from_json(v: &Value) -> JResult<Option<Extent>> {
        match v {
            Value::Null => Ok(None),
            Value::Object(m) => {
                let mut e = Extent::default();
                for (k, val) in m {
                    if is_ignored_prop(k) {
                        continue;
                    }
                    e.apply(k, val)?;
                }
                Ok(Some(e))
            }
            _ => err("expected an extent"),
        }
    }

    pub fn to_json(&self) -> Value {
        json!({
            "id": opt_i32(&self.id),
            "lowerLeft": point_json(&self.lower_left),
            "upperRight": point_json(&self.upper_right),
        })
    }
}

fn extent_json(o: &Option<Extent>) -> Value {
    null_or(o, |e| e.to_json())
}

