            "name" => self.name = string_opt(v)?,
            "owner" => {
                self.owner = match v {
                    Value::Null => None,
                    _ => Some(Box::new(User::from_json(v)?)),
                }
            }
            "members" => {
                self.members = match v {
                    Value::Null => None,
                    _ => {
                        let list = array(v)?
                            .iter()
                            .map(User::from_json)
                            .collect::<JResult<Vec<_>>>()?;
                        Some(dedupe_by(list, user_key))
                    }
                }
