            "roles" => {
                self.roles = match v {
                    Value::Null => None,
                    _ => {
                        let list = array(v)?
                            .iter()
                            .map(Role::from_json)
                            .collect::<JResult<Vec<_>>>()?;
                        Some(dedupe_by(list, role_key))
                    }
                }
            }
            _ => return err(format!("unknown property {k} on UserGroup")),
        }
        Ok(())
    }

    pub fn from_json(v: &Value) -> JResult<UserGroup> {
        let mut g = UserGroup::default();
        for (k, val) in obj(v)? {
            if is_ignored_prop(k) {
                continue;
            }
            g.apply(k, val)?;
        }
        Ok(g)
    }

    pub fn to_json(&self) -> Value {
        json!({
            "id": opt_i32(&self.id),
            "name": opt_str(&self.name),
            "owner": null_or(&self.owner, |u| u.to_json()),
            "members": vec_json(&self.members, |u| u.to_json()),
            "roles": vec_json(&self.roles, |r| r.to_json()),
        })
    }
}

