            properties: Some(vec![]),
            name: None,
            max_resolution: None,
            min_resolution: None,
            opacity: None,
            visible: None,
        }
    }
}

impl Appearance {
    pub fn apply(&mut self, k: &str, v: &Value) -> JResult<()> {
        match k {
            "id" => self.id = int_opt(v)?,
            "attribution" => self.attribution = string_opt(v)?,
            "hoverable" => self.hoverable = bool_opt(v)?,
            "clickable" => self.clickable = bool_opt(v)?,
            "hoverTemplate" => self.hover_template = string_opt(v)?,
            "properties" => {
                self.properties = match v {
                    Value::Null => None,
                    _ => Some(obj(v)?.iter().map(|(k, v)| (k.clone(), v.clone())).collect()),
                }
            }
            "name" => self.name = string_opt(v)?,
            "maxResolution" => self.max_resolution = f64_opt(v)?,
            "minResolution" => self.min_resolution = f64_opt(v)?,
            "opacity" => self.opacity = f64_opt(v)?,
            "visible" => self.visible = bool_opt(v)?,
            _ => return err(format!("unknown property {k} on LayerAppearance")),
        }
        Ok(())
    }

    pub fn from_json(v: &Value) -> JResult<Appearance> {
        let mut a = Appearance::default();
        for (k, val) in obj(v)? {
            if is_ignored_prop(k) {
                continue;
            }
            a.apply(k, val)?;
        }
        Ok(a)
    }

    pub fn bean() -> Appearance {
        Appearance::default()
    }

    pub fn to_json(&self) -> Value {
        let props = match &self.properties {
            Some(entries) => {
                let mut m = Map::new();
                for (k, v) in entries {
                    m.insert(k.clone(), v.clone());
                }
                Value::Object(m)
            }
            None => Value::Null,
        };
        json!({
            "id": opt_i32(&self.id),
            "attribution": opt_str(&self.attribution),
            "hoverable": opt_bool(&self.hoverable),
            "clickable": opt_bool(&self.clickable),
            "hoverTemplate": opt_str(&self.hover_template),
            "properties": props,
            "name": opt_str(&self.name),
            "maxResolution": opt_f64(&self.max_resolution),
            "minResolution": opt_f64(&self.min_resolution),
            "opacity": opt_f64(&self.opacity),
            "visible": opt_bool(&self.visible),
        })
    }
}

