    pub custom_request_path: Option<String>,
}

#[derive(Clone, Debug, Default)]
pub struct TileWms {
    pub image: ImageWms,
    pub tile_grid: Option<TileGrid>,
    pub request_with_tiled: Option<bool>,
}

#[derive(Clone, Debug, Default)]
pub struct Wfs {
    pub version: Option<String>,
    pub type_name: Option<String>,
    pub type_names: Option<String>,
}

#[derive(Clone, Debug, Default)]
pub struct Wmts {
    pub tile_grid: Option<TileGrid>,
    pub urls: Option<Vec<String>>,
    pub wmts_layer: Option<String>,
    pub wmts_style: Option<String>,
    pub projection: Option<String>,
    pub matrix_set: Option<String>,
    pub request_encoding: Option<String>,
    pub capabilities_url: Option<String>,
}

#[derive(Clone, Debug)]
pub struct Xyz {
    pub center: Option<Point>,
    pub extent: Option<Extent>,
    pub resolutions: Option<Vec<f64>>,
    pub tile_size: Option<i32>,
}

#[derive(Clone, Debug)]
pub enum DsKind {
    ImageWms(ImageWms),
    TileWms(TileWms),
    Wfs(Wfs),
    Wmts(Wmts),
    Xyz(Xyz),
}

#[derive(Clone, Debug)]
pub struct DataSource {
    pub id: Option<i32>,
    pub name: Option<String>,
    pub type_: Option<String>,
    pub url: Option<String>,
    pub format: Option<String>,
    pub kind: DsKind,
}

impl DataSource {
    pub fn apply(&mut self, k: &str, v: &Value) -> JResult<()> {
        match k {
            "id" => self.id = int_opt(v)?,
            "name" => self.name = string_opt(v)?,
            "type" => self.type_ = string_opt(v)?,
            "url" => self.url = string_opt(v)?,
            "format" => self.format = string_opt(v)?,
            _ => return self.apply_kind(k, v),
        }
        Ok(())
    }

    fn apply_kind(&mut self, k: &str, v: &Value) -> JResult<()> {
        match &mut self.kind {
            DsKind::ImageWms(i) => i.apply(k, v),
            DsKind::TileWms(t) => match k {
                "tileGrid" => {
                    t.tile_grid = TileGrid::from_json(v, false)?;
                    Ok(())
                }
                "requestWithTiled" => {
                    t.request_with_tiled = bool_opt(v)?;
                    Ok(())
                }
                _ => t.image.apply(k, v),
            },
            DsKind::Wfs(w) => match k {
                "version" => {
                    w.version = string_opt(v)?;
                    Ok(())
                }
                "typeName" => {
                    w.type_name = string_opt(v)?;
                    Ok(())
                }
                "typeNames" => {
                    w.type_names = string_opt(v)?;
                    Ok(())
                }
                _ => err(format!("unknown property {k} on WfsLayerDataSource")),
            },
            DsKind::Wmts(w) => match k {
                "tileGrid" => {
                    w.tile_grid = TileGrid::from_json(v, true)?;
                    Ok(())
                }
                "urls" => {
                    w.urls = str_list(v)?;
                    Ok(())
                }
                "wmtsLayer" => {
                    w.wmts_layer = string_opt(v)?;
                    Ok(())
                }
                "wmtsStyle" => {
                    w.wmts_style = string_opt(v)?;
                    Ok(())
                }
                "projection" => {
                    w.projection = string_opt(v)?;
                    Ok(())
                }
                "matrixSet" => {
                    w.matrix_set = string_opt(v)?;
                    Ok(())
                }
                "requestEncoding" => {
                    w.request_encoding = string_opt(v)?;
                    Ok(())
                }
                "capabilitiesUrl" => {
                    w.capabilities_url = string_opt(v)?;
                    Ok(())
                }
                _ => err(format!("unknown property {k} on WmtsLayerDataSource")),
            },
            DsKind::Xyz(x) => match k {
                "center" => {
                    x.center = Point::from_json(v)?;
                    Ok(())
                }
                "extent" => {
                    x.extent = Extent::from_json(v)?;
                    Ok(())
                }
                "resolutions" => {
                    x.resolutions = f64_list(v)?;
                    Ok(())
                }
                "tileSize" => {
                    x.tile_size = int_opt(v)?;
                    Ok(())
                }
                _ => err(format!("unknown property {k} on XyzLayerDataSource")),
            },
        }
    }

    pub fn to_json(&self) -> Value {
        let mut m = Map::new();
        m.insert("id".into(), opt_i32(&self.id));
        m.insert("name".into(), opt_str(&self.name));
        m.insert("type".into(), opt_str(&self.type_));
        m.insert("url".into(), opt_str(&self.url));
        m.insert("format".into(), opt_str(&self.format));
        match &self.kind {
            DsKind::ImageWms(i) => i.write_json(&mut m),
            DsKind::TileWms(t) => {
                t.image.write_json(&mut m);
                m.insert("tileGrid".into(), tile_grid_json(&t.tile_grid));
                m.insert("requestWithTiled".into(), opt_bool(&t.request_with_tiled));
            }
            DsKind::Wfs(w) => {
                m.insert("version".into(), opt_str(&w.version));
                m.insert("typeName".into(), opt_str(&w.type_name));
                m.insert("typeNames".into(), opt_str(&w.type_names));
            }
            DsKind::Wmts(w) => {
                m.insert("tileGrid".into(), tile_grid_json(&w.tile_grid));
                m.insert("urls".into(), vec_json(&w.urls, |s| Value::String(s.clone())));
                m.insert("wmtsLayer".into(), opt_str(&w.wmts_layer));
                m.insert("wmtsStyle".into(), opt_str(&w.wmts_style));
                m.insert("projection".into(), opt_str(&w.projection));
                m.insert("matrixSet".into(), opt_str(&w.matrix_set));
                m.insert("requestEncoding".into(), opt_str(&w.request_encoding));
                m.insert("capabilitiesUrl".into(), opt_str(&w.capabilities_url));
            }
            DsKind::Xyz(x) => {
                m.insert("center".into(), point_json(&x.center));
                m.insert("extent".into(), extent_json(&x.extent));
                m.insert("resolutions".into(), vec_json(&x.resolutions, |d| f64_val(*d)));
                m.insert("tileSize".into(), opt_i32(&x.tile_size));
            }
        }
        Value::Object(m)
    }
}

impl ImageWms {
    fn apply(&mut self, k: &str, v: &Value) -> JResult<()> {
        match k {
            "width" => self.width = int_prim(v)?,
            "height" => self.height = int_prim(v)?,
            "version" => self.version = string_opt(v)?,
            "layerNames" => self.layer_names = string_opt(v)?,
            "layerStyles" => self.layer_styles = string_opt(v)?,
            "requestableByPath" => self.requestable_by_path = bool_opt(v)?,
            "customRequestPath" => self.custom_request_path = string_opt(v)?,
            _ => return err(format!("unknown property {k} on ImageWmsLayerDataSource")),
        }
        Ok(())
    }

    fn write_json(&self, m: &mut Map<String, Value>) {
        m.insert("width".into(), Value::from(self.width));
        m.insert("height".into(), Value::from(self.height));
        m.insert("version".into(), opt_str(&self.version));
        m.insert("layerNames".into(), opt_str(&self.layer_names));
        m.insert("layerStyles".into(), opt_str(&self.layer_styles));
        m.insert("requestableByPath".into(), opt_bool(&self.requestable_by_path));
        m.insert("customRequestPath".into(), opt_str(&self.custom_request_path));
    }
}

// ---------------------------------------------------------------- Resource kinds

/// The six resources of the slice.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Res {
    Users,
    Groups,
    Roles,
    Layers,
    DataSources,
    Appearances,
}

/// Field types as the original's ConvertUtils converts query-string values.
#[derive(Clone, Copy, Debug, PartialEq)]
pub enum FType {
    Int,
    Str,
    Bool,
    Dbl,
}

/// A typed field value, used for filter comparisons.
#[derive(Clone, Debug, PartialEq)]
pub enum Cell {
    Int(Option<i32>),
    Str(Option<String>),
    Bool(Option<bool>),
    Dbl(Option<f64>),
}

impl Cell {
    pub fn to_json(&self) -> Value {
        match self {
            Cell::Int(i) => opt_i32(i),
            Cell::Str(s) => opt_str(s),
            Cell::Bool(b) => opt_bool(b),
            Cell::Dbl(d) => opt_f64(d),
        }
    }
}

impl Res {
    /// Field names that are restrictable and filterable: the private
    /// primitive, wrapper and String fields of the controller's entity class.
    pub fn fields(&self) -> &'static [(&'static str, FType)] {
        match self {
            Res::Users => &[
                ("id", FType::Int),
                ("firstName", FType::Str),
                ("lastName", FType::Str),
                ("email", FType::Str),
                ("accountName", FType::Str),
                ("password", FType::Str),
                ("active", FType::Bool),
            ],
            Res::Groups => &[("id", FType::Int), ("name", FType::Str)],
            Res::Roles => &[
                ("id", FType::Int),
                ("name", FType::Str),
                ("description", FType::Str),
            ],
            Res::Layers => &[
                ("id", FType::Int),
                ("name", FType::Str),
                ("description", FType::Str),
            ],
            Res::DataSources => &[
                ("id", FType::Int),
                ("name", FType::Str),
                ("type", FType::Str),
                ("url", FType::Str),
                ("format", FType::Str),
            ],
            Res::Appearances => &[
                ("id", FType::Int),
                ("attribution", FType::Str),
                ("hoverable", FType::Bool),
                ("clickable", FType::Bool),
                ("hoverTemplate", FType::Str),
                ("name", FType::Str),
                ("maxResolution", FType::Dbl),
                ("minResolution", FType::Dbl),
                ("opacity", FType::Dbl),
                ("visible", FType::Bool),
            ],
        }
    }
}

impl User {
    pub fn cell(&self, f: &str) -> Cell {
        match f {
            "id" => Cell::Int(self.id),
            "firstName" => Cell::Str(self.first_name.clone()),
            "lastName" => Cell::Str(self.last_name.clone()),
            "email" => Cell::Str(self.email.clone()),
            "accountName" => Cell::Str(self.account_name.clone()),
            "password" => Cell::Str(self.password.clone()),
            "active" => Cell::Bool(Some(self.active)),
            _ => Cell::Str(None),
        }
    }
}

impl UserGroup {
    pub fn cell(&self, f: &str) -> Cell {
        match f {
            "id" => Cell::Int(self.id),
            "name" => Cell::Str(self.name.clone()),
            _ => Cell::Str(None),
        }
    }
}

impl Role {
    pub fn cell(&self, f: &str) -> Cell {
        match f {
            "id" => Cell::Int(self.id),
            "name" => Cell::Str(self.name.clone()),
            "description" => Cell::Str(self.description.clone()),
            _ => Cell::Str(None),
        }
    }
}

impl Layer {
    pub fn cell(&self, f: &str) -> Cell {
        match f {
            "id" => Cell::Int(self.id),
            "name" => Cell::Str(self.name.clone()),
            "description" => Cell::Str(self.description.clone()),
            _ => Cell::Str(None),
        }
    }
}

impl DataSource {
    pub fn cell(&self, f: &str) -> Cell {
        match f {
            "id" => Cell::Int(self.id),
            "name" => Cell::Str(self.name.clone()),
            "type" => Cell::Str(self.type_.clone()),
            "url" => Cell::Str(self.url.clone()),
            "format" => Cell::Str(self.format.clone()),
            _ => Cell::Str(None),
        }
    }
}

impl Appearance {
    pub fn cell(&self, f: &str) -> Cell {
        match f {
            "id" => Cell::Int(self.id),
            "attribution" => Cell::Str(self.attribution.clone()),
            "hoverable" => Cell::Bool(self.hoverable),
            "clickable" => Cell::Bool(self.clickable),
            "hoverTemplate" => Cell::Str(self.hover_template.clone()),
            "name" => Cell::Str(self.name.clone()),
            "maxResolution" => Cell::Dbl(self.max_resolution),
            "minResolution" => Cell::Dbl(self.min_resolution),
            "opacity" => Cell::Dbl(self.opacity),
            "visible" => Cell::Bool(self.visible),
            _ => Cell::Str(None),
        }
    }
}

/// Converts a query-string value the way ConvertUtils does for the field type
/// (bad numbers become 0, bad booleans become false).
pub fn convert_query_value(t: FType, s: &str) -> Cell {
    match t {
        FType::Str => Cell::Str(Some(s.to_string())),
        FType::Int => Cell::Int(Some(s.trim().parse::<i32>().unwrap_or(0))),
        FType::Dbl => Cell::Dbl(Some(s.trim().parse::<f64>().unwrap_or(0.0))),
        FType::Bool => {
            let l = s.trim().to_lowercase();
            let b = matches!(l.as_str(), "true" | "yes" | "y" | "on" | "1");
            Cell::Bool(Some(b))
        }
    }
}

/// JSON of the default-constructed bean the original's projection creates for
/// each unselected field (`new User()`, `new UserGroup()`, ...).
pub fn res_json_bean(r: Res) -> Value {
    match r {
        Res::Users => User::bean().to_json(),
        Res::Groups => UserGroup::default().to_json(),
        Res::Roles => Role::default().to_json(),
        Res::Layers => Layer::default().to_json(),
        Res::Appearances => Appearance::bean().to_json(),
        Res::DataSources => Value::Null,
    }
}

