//! Tests of the port: the Jackson and Java conversions, the binding rules of the
//! entities, and (when DATABASE_URL is set) the HTTP behaviour against a database.

use serde_json::{Value, json};

use crate::json::*;
use crate::model::*;

// ---------------------------------------------------------------- Java formatting

#[test]
fn java_double_text_matches_double_tostring() {
    assert_eq!(java_double(1.0), "1.0");
    assert_eq!(java_double(-3.0), "-3.0");
    assert_eq!(java_double(0.1), "0.1");
    assert_eq!(java_double(156543.03390625), "156543.03390625");
    assert_eq!(java_double(1e10), "1.0E10");
    assert_eq!(java_double(1.5e-4), "1.5E-4");
    assert_eq!(java_double(12345678.0), "1.2345678E7");
    assert_eq!(java_double(0.001), "0.001");
    assert_eq!(java_double(0.0), "0.0");
}

#[test]
fn property_values_round_trip_the_converter() {
    assert_eq!(property_from_db("12"), json!(12));
    assert_eq!(property_from_db("-3"), json!(-3));
    assert_eq!(property_from_db("1.5"), json!(1.5));
    assert_eq!(property_from_db("true"), json!(true));
    assert_eq!(property_from_db("FALSE"), json!(false));
    // not parsable for commons-lang: an exponent or a trailing dot keeps the text
    assert_eq!(property_from_db("1.0E10"), json!("1.0E10"));
    assert_eq!(property_from_db("5."), json!("5."));
    assert_eq!(property_from_db("x"), json!("x"));
    assert_eq!(property_from_db(""), json!(""));

    assert_eq!(property_to_db(&json!(true)).unwrap(), "true");
    assert_eq!(property_to_db(&json!(5)).unwrap(), "5");
    assert_eq!(property_to_db(&json!(1.0)).unwrap(), "1.0");
    assert_eq!(property_to_db(&json!(1e10)).unwrap(), "1.0E10");
    assert_eq!(property_to_db(&json!("12")).unwrap(), "12");
    assert_eq!(property_to_db(&json!({"a": 1})).unwrap(), "{a=1}");
    assert_eq!(property_to_db(&json!([1, "x"])).unwrap(), "[1, x]");
    assert!(property_to_db(&Value::Null).is_err());
}

// ---------------------------------------------------------------- Jackson coercions

#[test]
fn integers_follow_jackson() {
    assert_eq!(int_opt(&json!("512")).unwrap(), Some(512));
    assert_eq!(int_opt(&json!(512.7)).unwrap(), Some(512));
    assert_eq!(int_opt(&Value::Null).unwrap(), None);
    assert_eq!(int_prim(&Value::Null).unwrap(), 0);
    assert!(int_opt(&json!("2.5")).is_err());
    assert!(int_opt(&json!("abc")).is_err());
    assert!(int_opt(&json!(true)).is_err());
}

#[test]
fn booleans_follow_jackson() {
    assert_eq!(bool_opt(&json!("true")).unwrap(), Some(true));
    assert_eq!(bool_opt(&json!(1)).unwrap(), Some(true));
    assert_eq!(bool_opt(&json!(0)).unwrap(), Some(false));
    assert!(bool_opt(&json!("yes")).is_err());
    assert_eq!(bool_prim(&Value::Null).unwrap(), false);
}

#[test]
fn strings_dates_and_locales() {
    assert_eq!(string_opt(&json!(5)).unwrap(), Some("5".to_string()));
    assert_eq!(string_opt(&json!(true)).unwrap(), Some("true".to_string()));
    assert!(string_opt(&json!([1])).is_err());
    assert!(date_opt(&json!("17.05.1990")).is_err());
