    assert_eq!(java_double(0.1), "0.1");
    assert_eq!(java_double(156543.03390625), "156543.03390625");
    assert_eq!(java_double(1e10), "1.0E10");
    assert_eq!(java_double(1.5e-4), "1.5E-4");
    assert_eq!(java_double(12345678.0), "1.2345678E7");
    assert_eq!(java_double(0.001), "0.001");
    assert_eq!(java_double(0.0), "0.0");
}

