    assert_eq!(property_to_db(&json!(1e10)).unwrap(), "1.0E10");
    assert_eq!(property_to_db(&json!("12")).unwrap(), "12");
    assert_eq!(property_to_db(&json!({"a": 1})).unwrap(), "{a=1}");
