new='''/// Connects, retrying for a while: the database may still be starting.
async fn connect(url: &str, max: u32) -> sqlx::PgPool {
    let mut attempt = 0;
    loop {
        match PgPoolOptions::new().max_connections(max).connect(url).await {
            Ok(pool) => return pool,
            Err(e) => {
                attempt += 1;
                if attempt >= 60 {
                    panic!("cannot connect to the database: {e}");
                }
                eprintln!("database not ready ({e}); retrying");
                tokio::time::sleep(std::time::Duration::from_secs(1)).await;
            }
        }
    }
}

#[tokio::main]
async fn main() {
    let url = std::env::var("DATABASE_URL").expect("DATABASE_URL must be set");
    let port: u16 = std::env::var("PORT")
        .ok()
        .and_then(|p| p.parse().ok())
        .unwrap_or(8080);

    // Request transactions use `pool`; id allocation uses `ids`, a separate pool,
    // so an id is never waited for while a transaction holds its connection.
    let pool = connect(&url, 16).await;
    let ids = connect(&url, 4).await;

    let state = Arc::new(rest::AppState { pool, ids });
    let app = Router::new().fallback(rest::handle).with_state(state);

    let listener = tokio::net::TcpListener::bind(("0.0.0.0", port))
        .await
        .expect("cannot bind the port");
    axum::serve(listener, app).await.expect("server failed");
}
'''
